    private void loadBackground(MapDef def) {
        int hour = new java.util.Date().getHours();
        bgStatus = bgStatusOverride >= 0 ? bgStatusOverride
            : (hour >= 18 || hour < 6) ? 1 : 0;
        if (def.bg == null) {
            bgSkyTex = null;
            bgLineTex = null;
            bgFullTex = null;
            cloudTex[0] = null;
            cloudTex[1] = null;
            clouds.clear();
            ensureWhiteTex();
            return;
        }
        // Bản chính 3.4.4 gộp nền trời + silhouette thành MỘT ảnh BGMap<bg><status>:
        // có file bgfull thì dùng chế độ một lớp, không có thì hai lớp bghd cũ.
        String fullPath = "bgfull/" + def.bgNum() + bgStatus + ".png";
        if (com.avatardk.game.GameFiles.data(fullPath).exists()) {
            bgFullTex = game.texture(fullPath);
            bgSkyTex = null;
            bgLineTex = null;
            // Chiều cao VẼ của nền: ảnh BGMap gốc thấp hơn dải imagemap
            // (465 so với 820 ở map 10) — neo đáy ở đáy map mà giữ chiều
            // cao thật thì đỉnh nền dừng giữa màn hình, bầu trời phía
            // trên thành màu phẳng rời rạc và silhouette không bao giờ
            // ló ra sau nhà (Tín chê "có background, trời là riêng"
            // 2026-11-04). Nền phải phủ kín tới đỉnh dải cảnh: kéo chiều
            // cao vẽ bằng chiều cao dải cao nhất (tối thiểu phủ hết
            // phần trời camera thấy khi map thấp hơn màn hình).
            bgFullDrawH = Math.max(mapBottomPx, mapBottomPx / 2f + Ui.H / 2f + 40f);
            for (Texture t : strips) {
                bgFullDrawH = Math.max(bgFullDrawH, t.getHeight());
            }
        } else {
            bgFullTex = null;
            bgSkyTex = game.texture("bghd/may" + def.bgNum() + bgStatus + ".png");
            bgLineTex = game.texture("bghd/" + def.bgNum() + bgStatus + ".png");
        }
        cloudTex[0] = game.texture("effect/cl0" + bgStatus + ".png");
        cloudTex[1] = game.texture("effect/cl1" + bgStatus + ".png");
        clouds.clear();
        java.util.Random rnd = new java.util.Random(1234 + def.id);
        float lineH = bgFullTex != null ? bgFullTex.getHeight()
            : bgLineTex != null ? bgLineTex.getHeight() : 200f;
        for (int i = 0; i < 8; i++) {
            Cloud c = new Cloud();
            c.anchor = i % 2;
            c.x100 = rnd.nextFloat() * (2200 + 800) * 100f;
            // dải mây của gốc nằm trên nóc ảnh silhouette một đoạn
            c.yW = mapBottomPx + lineH / 2f + 30 + rnd.nextFloat() * 170f;
            c.speed = 900 + rnd.nextFloat() * 900; // đơn vị x100/giây (~9–18 px/giây)
            clouds.add(c);
        }
        ensureWhiteTex();
    }

    private void ensureWhiteTex() {
        if (whiteTex == null) {
            com.badlogic.gdx.graphics.Pixmap pm =
                new com.badlogic.gdx.graphics.Pixmap(1, 1, com.badlogic.gdx.graphics.Pixmap.Format.RGBA8888);
            pm.setColor(Color.WHITE);
            pm.fill();
            whiteTex = new Texture(pm);
            pm.dispose();
        }
    }

    private void buildNpcs() {
        npcFigures.clear();
        // Vị trí + map của NPC lấy theo maps.json (đã đổi hệ: client id = npc.map + 1,
        // xem docs/maps-spec.md mục 0); hình + câu chat lấy từ dữ liệu NPC theo id.
        java.util.Map<Integer, NpcData> byId = new java.util.HashMap<>();
        for (NpcData n : game.data.npcs) byId.put(n.id, n);
        for (MapNpc mn : mapDef.npcs) {
            NpcData n = byId.get(mn.id);
            if (n == null) continue;
            NpcFigure f = new NpcFigure();
            f.data = n;
            f.doll = game.newDoll(n.items);
            f.feetX = mn.x * AvatarDkGame.HD;
            f.feetY = mapBottomPx - mn.y * AvatarDkGame.HD;
            f.anim.action = AvatarAnimator.STAND;
            npcFigures.add(f);
        }
    }

