    /** Chạm khi hộp xác nhận đang mở: trả true nếu đã nuốt chạm. */
    private boolean invConfirmTouch(float x, float y) {
        if (confirmText == null) return false;
        float pw = 480, ph = 176, cx0 = (Ui.W - pw) / 2f, cy0 = (Ui.H - ph) / 2f;
        if (x >= cx0 + 40 && x <= cx0 + 210 && y >= cy0 + 26 && y <= cy0 + 74) {
            invConfirmYes();
        } else if (x >= cx0 + pw - 210 && x <= cx0 + pw - 40 && y >= cy0 + 26 && y <= cy0 + 74) {
            confirmText = null;
        }
        return true;
    }

    /** Xử lý chạm cho panel GIỎ (2 tab). Toạ độ khớp drawInvPanel. */
    private void invTouch(float x, float y) {
        float px = (Ui.W - INV_W) / 2f, py = (Ui.H - INV_H) / 2f;
        if (splitOpen) {
            splitTouch(x, y);
            return;
        }
        if (invConfirmTouch(x, y)) return;
        // nút đóng: ô vuông trong góc phải trên
        if (x >= px + INV_W - 54 && x <= px + INV_W - 18
                && y >= py + INV_H - 54 && y <= py + INV_H - 18) {
            bagPanel = false;
            return;
        }
        if (x < px || x > px + INV_W || y < py || y > py + INV_H) {
            bagPanel = false;
            return;
        }
        // tabs (tab 3 = mở Rương phụ)
        float tabY = py + INV_H - 108;
        for (int i = 0; i < 3; i++) {
            float tx = px + 28 + i * 158;
            if (x >= tx && x <= tx + 146 && y >= tabY && y <= tabY + 38) {
                if (i == 2) {
                    openBox();
                } else {
                    bagTab = i;
                    bagSel = 0;
                }
                return;
            }
        }
        java.util.List<InvItem> items = invList(false);
        if (bagTab == 1) {
            // nút Sắp xếp ở cuối hàng tab
            float sw = 182;
            if (x >= px + INV_W - 28 - sw && x <= px + INV_W - 28
                    && y >= tabY && y <= tabY + 38) {
                closetSort = (closetSort + 1) % 3;
                closetPage = 0;
                bagSel = 0;
                return;
            }
            // hàng chip Lọc (khớp drawClosetGrid qua closetChipRect)
            float fy = tabY - 46, fh = 30;
            for (int i = 0; i < 8; i++) {
                float[] rc = closetChipRect(i, px);
                float fx = rc[0], fw = rc[1];
                if (x >= fx && x <= fx + fw && y >= fy && y <= fy + fh) {
                    closetFilter = i - 1;
                    closetPage = 0;
                    bagSel = 0;
                    return;
                }
            }
            // lưới tủ 5 x 2 + phân trang (khớp drawClosetGrid)
            float gx = px + 28 + 166;
            float gridTopC = py + INV_H - 180;
            int cols = 5, cell = 84, gap = 10;
            int pages = Math.max(1, (items.size() + 9) / 10);
            if (closetPage >= pages) closetPage = pages - 1;
            if (pages > 1 && y >= py + 100 && y <= py + 132) {
                float gridW = cols * cell + (cols - 1) * gap;
                if (x >= gx && x <= gx + 44) {
                    if (closetPage > 0) { closetPage--; bagSel = closetPage * 10; }
                    return;
                }
                if (x >= gx + gridW - 44 && x <= gx + gridW) {
                    if (closetPage < pages - 1) { closetPage++; bagSel = closetPage * 10; }
                    return;
                }
            }
            for (int idx = 0; idx < 10; idx++) {
                int gi = closetPage * 10 + idx;
                int col = idx % cols, row = idx / cols;
                float cx = gx + col * (cell + gap);
                float cy = gridTopC - (row + 1) * cell - row * gap;
                if (x >= cx && x <= cx + cell && y >= cy && y <= cy + cell) {
                    if (gi < items.size()) bagSel = gi;
                    return;
                }
            }
            // nút hành động ở thanh dưới (dùng chung đoạn dưới)
            if (!items.isEmpty() && bagSel < items.size()) {
                String[] acts = invActions(false);
                float by = py + 22;
                for (int i = 0; i < acts.length; i++) {
                    float bx = px + INV_W - 28 - (acts.length - i) * 132 + 12;
                    if (x >= bx && x <= bx + 120 && y >= by + 13 && y <= by + 53) {
                        invActionTapped(false, i, 0);
                        return;
                    }
                }
            }
            return;
        }
        // lưới ô
        float gridTop = py + INV_H - 128;
        int cols = 7, cell = 84, gap = 10;
        for (int idx = 0; idx < cols * 3; idx++) {
            int col = idx % cols, row = idx / cols;
            float cx = px + 28 + col * (cell + gap);
            float cy = gridTop - (row + 1) * cell - row * gap;
            if (x >= cx && x <= cx + cell && y >= cy && y <= cy + cell) {
                if (idx < items.size()) bagSel = idx;
                return;
            }
        }
        // nút hành động ở thanh dưới
        if (!items.isEmpty() && bagSel < items.size()) {
            String[] acts = invActions(false);
            float by = py + 22;
            for (int i = 0; i < acts.length; i++) {
                float bx = px + INV_W - 28 - (acts.length - i) * 132 + 12;
                if (x >= bx && x <= bx + 120 && y >= by + 13 && y <= by + 53) {
                    invActionTapped(false, i, 0);
                    return;
                }
            }
        }
    }

    /** Xử lý chạm cho panel RƯƠNG song song. Toạ độ khớp drawChestPanels. */
    private void chestTouch(float x, float y) {
        if (invConfirmTouch(x, y)) return;
        float py = CH_PY;
        // nút đóng: ô vuông trong góc phải trên của panel phải
        if (x >= CH_X0 + CH_PW * 2 + CH_GAP - 54 && x <= CH_X0 + CH_PW * 2 + CH_GAP - 18
                && y >= py + CH_PH - 54 && y <= py + CH_PH - 18) {
            chestPanel = false;
            return;
        }
        boolean inside = false;
        for (int side = 0; side < 2; side++) {
            float px = CH_X0 + side * (CH_PW + CH_GAP);
            if (x < px || x > px + CH_PW || y < py || y > py + CH_PH) continue;
            inside = true;
            boolean boxSideT = side == 1 && chestMode == 1;
            java.util.List<InvItem> items = side == 0 ? chestConItems
                : boxSideT ? boxItems : chestItems;
            int sel = side == 0 ? conSel : boxSideT ? boxSel : homeSel;
            // lưới ô 6 × 3
            float gridTop = py + CH_PH - 128;
            int cols = 6, cell = 84, gap = 8;
            float gridX = px + (CH_PW - (cols * cell + (cols - 1) * gap)) / 2f;
            for (int idx = 0; idx < cols * 3; idx++) {
                int col = idx % cols, row = idx / cols;
                float cx = gridX + col * (cell + gap);
                float cy = gridTop - (row + 1) * cell - row * gap;
                if (x >= cx && x <= cx + cell && y >= cy && y <= cy + cell) {
                    if (idx < items.size()) {
                        if (side == 0) conSel = idx;
                        else if (boxSideT) boxSel = idx;
                        else homeSel = idx;
                    }
                    return;
                }
            }
            // nút Di chuyển ở thanh dưới của phía này
            if (!items.isEmpty() && sel < items.size()) {
                float by = py + 22;
                float bx = px + CH_PW - 28 - 132 + 12;
                if (x >= bx && x <= bx + 120 && y >= by + 13 && y <= by + 53) {
                    invActionTapped(true, 0, side);
                    return;
                }
            }
            // nút Nâng cấp + Mật khẩu ở phía rương (nhà −90 / phụ −118)
            if (side == 1) {
                float by = py + 22;
                float ubx = px + CH_PW - 28 - 132 - 122 + 12;
                if (x >= ubx && x <= ubx + 110 && y >= by + 13 && y <= by + 53) {
                    if (online()) {
                        try {
                            if (boxSideT) AvatarProtocol.boxUpgrade(game.connection, 0);
                            else AvatarProtocol.upgradeChest(game.connection, 0);
                        } catch (IOException ignored) {
                        }
                    } else {
                        addChatLog(TAB_SYSTEM, null, "Đăng nhập để nâng cấp rương.", true);
                    }
                    return;
                }
                if (boxSideT) {
                    // nút Mật khẩu (nút Nâng cấp đã xử ở nhánh chung
                    // ngay trên, cùng toạ độ bản vẽ của rương phụ)
                    float pbx = px + CH_PW - 28 - 132 - 112 + 12 - 112;
                    if (x >= pbx && x <= pbx + 100 && y >= by + 13 && y <= by + 53) {
                        openBoxPassForm(boxHasPass ? 2 : 1);
                        return;
                    }
                }
            }
            return; // trong panel: nuốt chạm
        }
        if (!inside) chestPanel = false;
    }



