    // ----- Chuyển map ở mép đường: nông trại ↔ đường ra (26) ↔ khu 1 -----
    // Gốc ra/vào nông trại bằng cách ĐI BỘ qua miệng đường (FarmScr gửi
    // doJoinPark(25) khi ra đường); bản port trước đây chỉ nhảy map qua
    // bản đồ thành phố nên map 26 không tới được. Chỉ 3 map này nối
    // nhau bằng mép đường; các map khác vẫn đi qua bản đồ thành phố.
    private float edgeCd = 0f;

    private void updateEdgeTransitions(float dt) {
        if (edgeCd > 0f) {
            edgeCd -= dt;
            return;
        }
        if (mapDef == null || anyModalOpen()) return;
        if (mapDef.id == 25) {
            // miệng đường phía tây nông trại (cột ô 0–1, nửa trên cảnh —
            // nơi bếp/kho đứng) → sang đường ra nông trại
            if (playerX <= 50f && playerY >= 110f) {
                gotoMap(26, -70f, 130f);
            }
        } else if (mapDef.id == 26) {
            float eastX = worldW / AvatarDkGame.HD - 50f;
            if (playerX >= eastX) {
                gotoMap(25, 70f, 130f); // mép đông đường ra = cổng nông trại
            } else if (playerX <= 50f) {
                loadMap(findMap(1)); // mép tây = về Khu Mặt trời
                spawnPlayer();
                edgeCd = 1.2f;
            }
        }
    }

    /** Sang map kề qua mép đường: spawnX âm = lùi từ mép phải vào. */
    private void gotoMap(int mapId, float spawnX, float spawnY) {
        weddingOn = false; // rời map = hết trạng thái lễ (như gốc)
        // Trường đua (map 108): vào = bật chế độ đua, rời map = thoát đua
        if (raceIn && mapId != 108) {
            raceIn = false;
            raceLocal = false;
            raceWinOpen = raceHistOpen = raceDcOpen = raceExitConfirm = false;
            if (online()) {
                try {
                    Msg h = new Msg(AvatarProtocol.GET_HANDLER);
                    h.writer().writeByte(9);
                    game.connection.send(h);
                } catch (Exception ignored) {
                }
            }
        }
        if (mapId == 108 && !raceIn) {
            raceReturnMap = mapDef != null ? mapDef.id : 10;
            raceReturnX = playerX;
            raceReturnY = playerY;
        }
        loadMap(findMap(mapId));
        playerX = spawnX < 0 ? worldW / AvatarDkGame.HD + spawnX : spawnX;
        playerY = spawnY;
        if (!canStand(playerX, playerY)) {
            boolean found = false;
            for (int r = 1; r <= 6 && !found; r++) {
                for (int dx = -r; dx <= r && !found; dx++) {
                    for (int dy = -r; dy <= r && !found; dy++) {
                        float tx = playerX + dx * 24, ty = playerY + dy * 24;
                        if (canStand(tx, ty)) {
                            playerX = tx;
                            playerY = ty;
                            found = true;
                        }
                    }
                }
            }
        }
        edgeCd = 1.2f;
        if (mapId == 108 && !raceIn) startRaceMode();
    }

    // ===== Cổng LinkMap của bản chính 3.4.4 (docs/maps-344-audit.md §2.3) =====
    // Hình chữ nhật ở mép map: bước vào (hoặc va vào ô trong vùng) là
    // chuyển sang map đích. Toạ độ x1,y1,x2,y2 tính bằng 1/10 ô trong hệ
    // trên–trái của lưới (nhân 2,4 ra medium). {map nguồn, x1, y1, x2, y2,
    // map đích} — id đều là id phía client.
    private static final int[][] LINK_PORTALS = {
        {10, 70, 15, 90, 25, 30},
        {18, 80, 0, 100, 10, 21},
        {18, 310, 0, 340, 10, 23},
        {18, 510, 0, 540, 10, 27},
        {21, 120, 60, 140, 70, 18},
        {21, 0, 50, 10, 70, 28},
        {23, 120, 70, 160, 80, 18},
        {27, 110, 70, 140, 80, 18},
        {28, 270, 70, 280, 90, 21},
        {30, 120, 190, 140, 200, 10},
    };
    // Chống dội cổng: vừa qua cổng thì cổng ở map mới chưa "nạp" — chỉ
    // nạp lại khi người chơi đã ra hẳn khỏi mọi vùng cổng của map đó.
    private boolean linkArm = true;

    /** Map đích nếu điểm (mx, my) nằm trong một vùng cổng LinkMap của
     *  map hiện tại; −1 nếu không. */
    private int linkDestAt(int mapId, float mx, float my) {
        for (int[] L : LINK_PORTALS) {
            if (L[0] != mapId) continue;
            if (mx >= L[1] * 2.4f && mx <= L[3] * 2.4f
                && my >= L[2] * 2.4f && my <= L[4] * 2.4f) return L[5];
        }
        return -1;
    }

    /** Qua cổng LinkMap sang map đích: đáp tại tâm cổng ngược (cổng ở
     *  map đích trỏ về map nguồn), gotoMap tự tìm ô đứng được gần nhất. */
    private void linkTravel(int dest) {
        int from = mapDef.id;
        float ax = -1f, ay = -1f;
        for (int[] L : LINK_PORTALS) {
            if (L[0] == dest && L[5] == from) {
                ax = (L[1] + L[3]) / 2f * 2.4f;
                ay = (L[2] + L[4]) / 2f * 2.4f;
                break;
            }
        }
        linkArm = false;
        if (ax >= 0f) {
            gotoMap(dest, ax, ay);
        } else {
            loadMap(findMap(dest));
            spawnPlayer();
            edgeCd = 1.2f;
        }
    }

    /** Bước hẳn vào vùng cổng (không cần va) cũng qua cổng; đồng thời
     *  quản nhịp nạp lại cổng sau mỗi lần qua. */
    private void updateLinkPortals() {
        if (mapDef == null || houseIn || farmIn || anyModalOpen()) return;
        int d = linkDestAt(mapDef.id, playerX, playerY);
        if (!linkArm) {
            if (d < 0) linkArm = true;
            return;
        }
        if (d > 0 && edgeCd <= 0f) linkTravel(d);
    }

