    // ---------- Tiến Lên: xử lý gói (docs/tienlen-spec.md) ----------

    private int csSeatIdx(int id) {
        for (int i = 0; i < csSeats.length; i++) {
            if (csSeats[i].id == id) return i;
        }
        return -1;
    }

    /** START {room, board, byte interval, 13 lá, int whoMoveFirst}. */
    private void tlOnStart(java.io.DataInputStream r) throws Exception {
        r.readByte();
        r.readByte();
        tlIntervalSecs = r.readUnsignedByte();
        if (tlIntervalSecs <= 0) tlIntervalSecs = 30;
        tlHand.clear();
        tlSel.clear();
        tlTable.clear();
        tlResults.clear();
        tlShown.clear();
        for (int i = 0; i < 13; i++) tlHand.add(r.readUnsignedByte());
        java.util.Collections.sort(tlHand);
        int firstId = r.readInt();
        for (int s = 0; s < 4; s++) tlCounts[s] = csSeats[s].id != -1 ? 13 : 0;
        tlTurnId = firstId;
        tlTurnEndMs = System.currentTimeMillis() + tlIntervalSecs * 1000L;
        tlPlaying = true;
        tlStopped = false;
        tlTableSeat = -1;
        tlShownId = -1;
        tlStatus = "";
        tlMustInclude0 = firstId == ownId() && tlHand.contains(0);
        for (CsSeat seat : csSeats) seat.ready = false;
        // đúng gốc: client tự gửi forceFinish sau mỗi lần chia bài,
        // server tự kiểm tới trắng bằng bài thật rồi mới kết thúc ván
        csSend(csMsgRB(CS_FORCE));
    }

    /** MOVE {room, board, int who, byte n, n lá, int nextMove}. */
    private void tlOnMove(java.io.DataInputStream r) throws Exception {
        r.readByte();
        r.readByte();
        int who = r.readInt();
        int n = r.readUnsignedByte();
        java.util.List<Integer> cards = new ArrayList<>();
        for (int i = 0; i < n; i++) cards.add(r.readUnsignedByte());
        int next = r.readInt();
        tlTable.clear();
        tlTable.addAll(cards);
        int si = csSeatIdx(who);
        tlTableSeat = si;
        if (si >= 0) tlCounts[si] = Math.max(0, tlCounts[si] - n);
        if (who == ownId()) {
            for (int c : cards) tlHand.remove(Integer.valueOf(c));
            tlSel.clear();
            tlMustInclude0 = false;
        }
        tlTurnId = next;
        tlTurnEndMs = System.currentTimeMillis() + tlIntervalSecs * 1000L;
        tlStatus = "";
    }

    /** SKIP {room, board, int whoSkip, int nextMove, bool clear}. */
    private void tlOnSkip(java.io.DataInputStream r) throws Exception {
        r.readByte();
        r.readByte();
        r.readInt();
        int next = r.readInt();
        boolean clear = r.readBoolean();
        if (clear) {
            tlTable.clear();
            tlTableSeat = -1;
            tlStatus = "";
        }
        tlTurnId = next;
        tlTurnEndMs = System.currentTimeMillis() + tlIntervalSecs * 1000L;
    }

    /** FINISH {room, board, int who, byte pos (0-based), int dMoney, int dExp}. */
    private void tlOnFinish(java.io.DataInputStream r) throws Exception {
        r.readByte();
        r.readByte();
        int who = r.readInt();
        int pos = r.readUnsignedByte();
        int dMoney = r.readInt();
        r.readInt(); // dExp
        tlResults.put(who, new int[]{pos, dMoney});
        int si = csSeatIdx(who);
        if (si >= 0) {
            tlCounts[si] = 0;
            // xu hiển thị của ghế cộng delta tại chỗ (gói đồng bộ tiền
            // tuyệt đối của server chỉ cập nhật myXu, không cập nhật ghế)
            csSeats[si].xu += dMoney;
        }
    }

    /** STOP {room, board} hoặc kèm {int whoShow, byte n, n lá} khi ván huỷ. */
    private void tlOnStop(java.io.DataInputStream r) throws Exception {
        r.readByte();
        r.readByte();
        tlShown.clear();
        tlShownId = -1;
        if (r.available() > 0) {
            tlShownId = r.readInt();
            int n = r.readUnsignedByte();
            for (int i = 0; i < n; i++) tlShown.add(r.readUnsignedByte());
        }
        tlPlaying = false;
        tlStopped = true;
        tlTurnId = -1;
        tlSel.clear();
    }

    /** FORCE_FINISH {room, board, int who, 13 lá của người tới trắng}. */
    private void tlOnForce(java.io.DataInputStream r) throws Exception {
        r.readByte();
        r.readByte();
        int who = r.readInt();
        tlShown.clear();
        for (int i = 0; i < 13; i++) tlShown.add(r.readUnsignedByte());
        tlShownId = who;
        tlPlaying = false;
        tlStopped = true;
        tlTurnId = -1;
        tlSel.clear();
        CsSeat s = who >= 0 ? csSeatById(who) : null;
        tlStatus = (s != null ? s.name : "Một người chơi") + " tới trắng!";
    }

    // ---------- Phỏm: xử lý gói (docs/phom-spec.md) ----------

    /** START {room, board, byte interval, 9 lá, int firstMove, int firHa}. */
    private void phOnStart(java.io.DataInputStream r) throws Exception {
        r.readByte();
        r.readByte();
        phIntervalSecs = r.readUnsignedByte();
        if (phIntervalSecs <= 0) phIntervalSecs = 30;
        phReset();
        for (int i = 0; i < 9; i++) phHand.add(r.readUnsignedByte());
        java.util.Collections.sort(phHand);
        int first = r.readInt();
        r.readInt(); // firHa = first lúc bắt đầu
        for (int s = 0; s < 4; s++) phCounts[s] = csSeats[s].id != -1 ? 9 : 0;
        phTurnId = first;
        phPhase = 0;
        phPlaying = true;
        phTurnEndMs = System.currentTimeMillis() + phIntervalSecs * 1000L;
        for (CsSeat seat : csSeats) seat.ready = false;
    }

    /** FIRE {room, board, int next, int firer, byte card (−1 = sai), byte numberCard}. */
    private void phOnFire(java.io.DataInputStream r) throws Exception {
        r.readByte();
        r.readByte();
        int next = r.readInt();
        int firer = r.readInt();
        int card = r.readByte();
        r.readByte(); // numberCard
        if (card < 0) { // nước sai — chỉ người đánh nhận, lượt giữ nguyên
            phStatus = "Lá đó không đánh được";
            phTurnEndMs = System.currentTimeMillis() + phIntervalSecs * 1000L;
            return;
        }
        int fs = csSeatIdx(firer);
        if (fs >= 0) {
            phDiscards.get(fs).add(card);
            phCounts[fs] = Math.max(0, phCounts[fs] - 1);
        }
        if (firer == ownId()) {
            phHand.remove(Integer.valueOf(card));
            phSel.clear();
            phMyFires++;
            if (csMySeat >= 0) phCounts[csMySeat] = phHand.size();
        }
        phTableCard = card;
        phTableFromSeat = fs;
        phTurnId = next;
        phPhase = 0;
        phStatus = "";
        phTurnEndMs = System.currentTimeMillis() + phIntervalSecs * 1000L;
    }

    /** SKIP {room, board, int next, int firHa} — hết giờ, lá trên bàn giữ nguyên. */
    private void phOnSkip(java.io.DataInputStream r) throws Exception {
        r.readByte();
        r.readByte();
        int next = r.readInt();
        int firHa = r.readInt();
        phTurnId = next;
        phTableFromSeat = csSeatIdx(firHa);
        phPhase = 0;
        phTurnEndMs = System.currentTimeMillis() + phIntervalSecs * 1000L;
    }

    /** GET_CARD {room, board, byte card} — chỉ người bốc nhận. */
    private void phOnGet(java.io.DataInputStream r) throws Exception {
        r.readByte();
        r.readByte();
        int card = r.readUnsignedByte();
        phHand.add(card);
        java.util.Collections.sort(phHand);
        phPhase = 1;
        phStatus = "";
        if (csMySeat >= 0) phCounts[csMySeat] = phHand.size();
        phTurnEndMs = System.currentTimeMillis() + phIntervalSecs * 1000L;
    }

    /** EAT {room, board, int firHa, bool isEat, [byte numEat], byte nCard}. */
    private void phOnEat(java.io.DataInputStream r) throws Exception {
        r.readByte();
        r.readByte();
        int firHa = r.readInt();
        boolean isEat = r.readBoolean();
        if (!isEat) { // chỉ người ăn hụt nhận
            r.readByte(); // nCard
            phPendingEat = null;
            phStatus = "Ăn không được — bốc bài hoặc chọn lá khác";
            return;
        }
        int numEat = r.readUnsignedByte();
        r.readByte(); // nCard
        int fhSeat = csSeatIdx(firHa);
        if (fhSeat >= 0 && !phDiscards.get(fhSeat).isEmpty()) {
            phDiscards.get(fhSeat).remove(phDiscards.get(fhSeat).size() - 1);
        }
        int eaterSeat = csSeatIdx(phTurnId); // lượt chưa đổi = người ăn
        int eatenCard = phTableCard;
        if (eaterSeat >= 0) {
            phCounts[eaterSeat]++;
            if (phTurnId == ownId() && phPendingEat != null) {
                java.util.List<Integer> meld = new ArrayList<>();
                for (int c : phPendingEat) {
                    phLocked.add(c);
                    meld.add(c);
                }
                if (eatenCard >= 0) {
                    phLocked.add(eatenCard);
                    meld.add(eatenCard);
                }
                java.util.Collections.sort(meld);
                phMelds.get(eaterSeat).addAll(meld);
                if (csMySeat >= 0) phCounts[csMySeat] = phHand.size();
                phPendingEat = null;
            } else {
                // phỏm của đối thủ: numEat lá úp + lá vừa ăn (thấy được)
                for (int i = 0; i < numEat; i++) phMelds.get(eaterSeat).add(-1);
                if (eatenCard >= 0) phMelds.get(eaterSeat).add(eatenCard);
            }
        }
        phTableCard = -1;
        phTableFromSeat = -1;
        if (phTurnId == ownId()) phPhase = 1;
        phStatus = "";
        phTurnEndMs = System.currentTimeMillis() + phIntervalSecs * 1000L;
    }

    /** HA_PHOM {room, board, int curID, bool isHa, bool isU,
     *  [4 × int dMoney, các lá đã hạ cách nhau −1]}. */
    private void phOnHa(java.io.DataInputStream r) throws Exception {
        r.readByte();
        r.readByte();
        int cur = r.readInt();
        boolean isHa = r.readBoolean();
        boolean isU = r.readBoolean();
        if (!isHa) { // chỉ người hạ nhận
            phStatus = "Phỏm không khớp — hạ lại";
            return;
        }
        int[] deltas = new int[4];
        for (int s = 0; s < 4; s++) deltas[s] = r.readInt();
        java.util.List<Integer> down = new ArrayList<>();
        while (r.available() > 0) {
            int v = r.readByte();
            if (v != -1) down.add(v & 0xFF);
        }
        int cs = csSeatIdx(cur);
        if (cs >= 0) phMelds.get(cs).addAll(down);
        if (cur == ownId()) {
            phHaDone = true;
            phLocked.addAll(down);
            phStatus = "Đã hạ phỏm — đánh lá cuối";
        }
        if (isU) {
            phPlaying = false;
            phStopped = true;
            CsSeat w = csSeatById(cur);
            phBanner = (w != null ? w.name : "Một người chơi") + " ù!";
            for (int s = 0; s < 4; s++) {
                if (csSeats[s].id != -1) {
                    phResults.put(csSeats[s].id, new int[]{-1, deltas[s]});
                    csSeats[s].xu += deltas[s];
                }
            }
        }
    }

    /** DEN_BAI {room, board, int winID, 4 × int dMoney theo ghế}. */
    private void phOnDen(java.io.DataInputStream r) throws Exception {
        r.readByte();
        r.readByte();
        int win = r.readInt();
        phDenWinnerId = win;
        for (int s = 0; s < 4; s++) {
            int d = r.readInt();
            if (csSeats[s].id != -1) {
                phResults.put(csSeats[s].id, new int[]{-1, d});
                csSeats[s].xu += d;
            }
        }
        phPlaying = false;
        phStopped = true;
        CsSeat w = csSeatById(win);
        phBanner = (w != null ? w.name : "Một người chơi") + " ù — có người đền ù!";
    }

    /** FINISH {room, board, 4 × int dMoney, 4 × int score, rác 4 ghế cách −1}. */
    private void phOnFinish(java.io.DataInputStream r) throws Exception {
        r.readByte();
        r.readByte();
        int[] money = new int[4];
        int[] score = new int[4];
        for (int s = 0; s < 4; s++) money[s] = r.readInt();
        for (int s = 0; s < 4; s++) score[s] = r.readInt();
        java.util.List<java.util.List<Integer>> rac = new ArrayList<>();
        for (int i = 0; i < 4; i++) rac.add(new ArrayList<Integer>());
        int cur = 0;
        while (r.available() > 0) {
            int v = r.readByte();
            if (v == -1) cur++;
            else if (cur < 4) rac.get(cur).add(v & 0xFF);
        }
        for (int s = 0; s < 4; s++) {
            if (csSeats[s].id != -1) {
                phResults.put(csSeats[s].id, new int[]{score[s], money[s]});
                phRac.put(csSeats[s].id, rac.get(s));
                csSeats[s].xu += money[s];
            }
        }
        phPlaying = false;
        phStopped = true;
        phTurnId = -1;
    }

    /** STOP — ván huỷ vì có người rời giữa ván. */
    private void phOnStop(java.io.DataInputStream r) throws Exception {
        r.readByte();
        r.readByte();
        phPlaying = false;
        phStopped = true;
        phTurnId = -1;
        phResults.clear();
        phStatus = "Ván bị huỷ — có người rời bàn";
    }

