    public void debugCasinoBoards() {
        casinoIn = true;
        csPending = false;
        casinoPage = 1;
        csRoomId = 43;
        csStatus = "";
        csBoards.clear();
        int[][] bb = {{0, 2, 5, 1000, 0}, {1, 5, 5, 5000, 0}, {2, 0, 5, 0, 0},
            {3, 3, 5, 500, 2}, {4, 1, 5, 10000, 1}, {5, 4, 5, 2000, 0}};
        for (int[] r : bb) {
            CsBoardInfo b = new CsBoardInfo();
            b.id = r[0];
            b.n = r[1];
            b.max = r[2];
            b.money = r[3];
            b.playing = (r[4] & 2) != 0;
            b.pass = (r[4] & 1) != 0;
            csBoards.add(b);
        }
    }

