    // ---------- Casino: vẽ + chạm ----------
    private static final float CS_PX = 16f, CS_PY = 16f, CS_PW = 1248f, CS_PH = 688f;

    private void bcEnsureRegions() {
        if (bcDoorRegions != null || house == null) return;
        Texture doorTex = house.imgTexture(872);
        Texture diceTex = house.imgTexture(874);
        if (doorTex == null || diceTex == null) return;
        bcDoorRegions = new com.badlogic.gdx.graphics.g2d.TextureRegion[6];
        for (int i = 0; i < 6; i++) {
            bcDoorRegions[i] = new com.badlogic.gdx.graphics.g2d.TextureRegion(
                doorTex, 0, i * 96, 96, 96);
        }
        bcDiceRegions = new com.badlogic.gdx.graphics.g2d.TextureRegion[8];
        for (int i = 0; i < 8; i++) {
            bcDiceRegions[i] = new com.badlogic.gdx.graphics.g2d.TextureRegion(
                diceTex, 0, i * 108, 108, 108);
        }
    }

    private void csPanelBase(String title, String sub) {
        batch.setColor(0f, 0f, 0f, 0.45f);
        batch.draw(whiteTex, 0, 0, Ui.W, Ui.H);
        batch.setColor(Color.WHITE);
        batch.draw(Ui.roundedRect((int) CS_PW, (int) CS_PH, 18,
            new Color(0.07f, 0.11f, 0.17f, 0.98f), GLASS_RIM), CS_PX, CS_PY);
        Ui.fontTitle.setColor(1f, 0.85f, 0.38f, 1f);
        Ui.fontTitle.draw(batch, title, CS_PX + 28, CS_PY + CS_PH - 30);
        if (sub != null && !sub.isEmpty()) {
            Ui.fontSmall.setColor(1f, 1f, 1f, 0.75f);
            Ui.fontSmall.draw(batch, sub, CS_PX + 28, CS_PY + CS_PH - 66);
        }
        batch.draw(Ui.roundedRect(36, 36, 10, Ui.BTN_CLOSE, GLASS_RIM),
            CS_PX + CS_PW - 54, CS_PY + CS_PH - 54);
        Ui.faIcon(batch, Ui.fa20, Ui.FA_XMARK, CS_PX + CS_PW - 36,
            CS_PY + CS_PH - 36, new Color(1f, 1f, 1f, 0.9f));
    }

    /** style: 0 đen · 1 cam gradient · 2 đỏ sẫm · 3 xám khoá. */
    private void csButton(float x, float y, float w, float h, String label, int style) {
        if (style == 1) {
            batch.draw(Ui.gradientRect((int) w, (int) h, 12,
                EntryUi.ORANGE_TOP, EntryUi.ORANGE_BOT), x, y);
        } else if (style == 2) {
            batch.draw(Ui.roundedRect((int) w, (int) h, 12,
                new Color(0.45f, 0.16f, 0.16f, 0.95f), GLASS_RIM), x, y);
        } else if (style == 3) {
            batch.draw(Ui.roundedRect((int) w, (int) h, 12,
                new Color(0.25f, 0.27f, 0.30f, 0.9f), GLASS_RIM), x, y);
        } else {
            batch.draw(Ui.roundedRect((int) w, (int) h, 12, Ui.BTN_CANCEL, GLASS_RIM), x, y);
        }
        Ui.centered(batch, Ui.font, label, x + w / 2f, y + h / 2f + 8, Color.WHITE);
    }

    private void drawCasino() {
        bcEnsureRegions();
        if (csPending && !casinoIn) {
            csPanelBase(csGameName(), null);
            Ui.centered(batch, Ui.font, "Đang vào casino…",
                640, 380, Color.WHITE);
            Ui.centered(batch, Ui.fontSmall, "Đang kết nối tới sảnh Casino",
                640, 344, new Color(1f, 1f, 1f, 0.7f));
            return;
        }
        if (casinoPage == 0) drawCsRooms();
        else if (casinoPage == 1) drawCsBoards();
        else if (csGame == 3) drawTlBoard();
        else if (csGame == 7) drawPhomBoard();
        else if (csGame == 21) drawDiamondBoard();
        else drawCsBoard();
        if (csMoneySheet) drawCsMoneySheet();
        if (csKickSheet) drawCsKickSheet();
    }

    private void drawCsRooms() {
        csPanelBase("Casino — " + csGameName(),
            "Chọn phòng để xem bàn");
        if (csRooms.isEmpty()) {
            Ui.centered(batch, Ui.font, "Chưa có phòng nào.",
                640, 380, new Color(1f, 1f, 1f, 0.8f));
        }
        int n = csRooms.size();
        float cw = 340, chh = 150, gap = 24;
        float total = n * cw + (n - 1) * gap;
        float sx = 640 - total / 2f, sy = 290;
        for (int i = 0; i < n; i++) {
            CsRoom rm = csRooms.get(i);
            float cx = sx + i * (cw + gap);
            batch.draw(Ui.roundedRect((int) cw, (int) chh, 14,
                new Color(0.10f, 0.16f, 0.24f, 0.97f), GLASS_RIM), cx, sy);
            Ui.centered(batch, Ui.fontTitle, "Phòng " + rm.id,
                cx + cw / 2f, sy + 106, new Color(1f, 0.85f, 0.38f, 1f));
            Ui.centered(batch, Ui.fontSmall, "Cấp độ " + (rm.lv + 1),
                cx + cw / 2f, sy + 64, Color.WHITE);
            Ui.centered(batch, Ui.fontTiny,
                "Trống: " + rm.free + " · Đang chờ: " + rm.wait,
                cx + cw / 2f, sy + 34, new Color(1f, 1f, 1f, 0.7f));
        }
        Ui.centered(batch, Ui.fontSmall, "Chạm vào một phòng để xem danh sách bàn.",
            640, 200, new Color(1f, 1f, 1f, 0.65f));
        csButton(CS_PX + 24, CS_PY + 24, 150, 48, "Thoát", 2);
    }

    private void drawCsBoards() {
        csPanelBase("Casino — " + csGameName(),
            "Phòng " + csRoomId + " · chọn một bàn hoặc tự tạo bàn");
        int pages = Math.max(1, (csBoards.size() + 5) / 6);
        if (csBoardPage >= pages) csBoardPage = pages - 1;
        float cw = 380, chh = 160, gx = 46, gyTop = 340, gyBot = 160;
        for (int i = 0; i < 6; i++) {
            int bi = csBoardPage * 6 + i;
            if (bi >= csBoards.size()) break;
            CsBoardInfo b = csBoards.get(bi);
            float cx = gx + (i % 3) * (cw + 24);
            float cy = (i / 3 == 0) ? gyTop : gyBot;
            float cTop = cy + chh;
            batch.draw(Ui.roundedRect((int) cw, (int) chh, 14,
                new Color(0.10f, 0.16f, 0.24f, 0.97f), GLASS_RIM), cx, cy);
            Ui.font.setColor(1f, 0.85f, 0.38f, 1f);
            Ui.font.draw(batch, "Bàn " + (b.id + 1), cx + 20, cTop - 38);
            String badge = b.playing ? "Đang chơi" : b.pass ? "Có mật khẩu" : "";
            if (!badge.isEmpty()) {
                Ui.fontTiny.setColor(1f, 0.75f, 0.4f, 1f);
                layout.setText(Ui.fontTiny, badge);
                Ui.fontTiny.draw(batch, badge, cx + cw - 20 - layout.width, cTop - 36);
            }
            Ui.fontSmall.setColor(Color.WHITE);
            Ui.fontSmall.draw(batch, "Người chơi: " + b.n + "/" + Math.max(b.max, 5),
                cx + 20, cTop - 84);
            Ui.fontSmall.setColor(1f, 1f, 1f, 0.8f);
            Ui.fontSmall.draw(batch, b.money > 0
                ? "Mức cược: " + fmtMoney(b.money) + " xu / đơn vị" : "Mức cược: chưa đặt",
                cx + 20, cTop - 122);
            if (b.n >= 5) {
                batch.setColor(0f, 0f, 0f, 0.45f);
                batch.draw(Ui.roundedRect((int) cw, (int) chh, 14,
                    new Color(0f, 0f, 0f, 0.45f), GLASS_RIM), cx, cy);
                batch.setColor(Color.WHITE);
                Ui.centered(batch, Ui.font, "Bàn đầy", cx + cw / 2f, cy + 100,
                    new Color(1f, 0.6f, 0.5f, 1f));
            }
        }
        if (!csStatus.isEmpty()) {
            Ui.centered(batch, Ui.fontSmall, csStatus, 640, CS_PY + 108,
                new Color(1f, 0.85f, 0.38f, 1f));
        }
        csButton(CS_PX + 24, CS_PY + 24, 150, 48, "Phòng", 0);
        csButton(CS_PX + CS_PW - 174, CS_PY + 24, 150, 48, "Thoát", 2);
        // [PORT] Tự tạo bàn: gốc không có gói tạo bàn riêng (vào bàn trống
        // là thành chủ bàn) — nút này nhờ server cấp một bàn trắng mới
        // (JOIN_BOARD với id −1) rồi vào ngay làm chủ bàn.
        csButton(CS_PX + (CS_PW - 240) / 2f, CS_PY + 24, 240, 48, "Tạo bàn mới", 1);
        if (pages > 1) {
            csButton(CS_PX + CS_PW / 2f - 190, CS_PY + 24, 48, 48, "<",
                csBoardPage > 0 ? 0 : 3);
            csButton(CS_PX + CS_PW / 2f + 142, CS_PY + 24, 48, 48, ">",
                csBoardPage < pages - 1 ? 0 : 3);
            Ui.centered(batch, Ui.fontTiny, "Trang " + (csBoardPage + 1) + "/" + pages,
                640, CS_PY + 88, new Color(0.85f, 0.92f, 1f, 0.9f));
        }
    }

    private float[] csSeatPos(int seat) {
        int rel = csMySeat >= 0 ? (seat - csMySeat + 5) % 5 : seat;
        switch (rel) {
            case 0: return new float[]{640, 208};
            case 1: return new float[]{1072, 300};
            case 2: return new float[]{1072, 545};
            case 3: return new float[]{208, 545};
            default: return new float[]{208, 300};
        }
    }

    private int csDoorTotal(int d) {
        int t = 0;
        for (int s = 0; s < 5; s++) t += csBetsSv[s][d];
        if (csPhase == 1 && !csBetLocked && csMySeat > 0) t += csMyBets[d];
        return t;
    }

    private void drawCsBoard() {
        CsSeat owner = csOwnerId >= 0 ? csSeatById(csOwnerId) : null;
        String sub = "Chủ bàn: " + (owner != null ? owner.name : "—")
            + (csBoardMoney > 0 ? " · Mức cược: " + fmtMoney(csBoardMoney) + " xu / đơn vị"
                : " · Chưa đặt mức cược");
        csPanelBase("Bầu Cua — Bàn " + (csBoardId + 1), sub);
        long now = System.currentTimeMillis();
        // pha + đồng hồ
        String phaseText = csFinished ? "Kết quả"
            : csPhase == 1 ? "Đang đặt cược"
            : csPhase == 2 ? "Đang tả" : csPhase == 3 ? "Mở xúc xắc" : "Sẵn sàng";
        Ui.centered(batch, Ui.font, phaseText, 640, CS_PY + CS_PH - 38,
            new Color(1f, 0.85f, 0.38f, 1f));
        if ((csPhase == 1 || csPhase == 2) && !csFinished) {
            long remain = Math.max(0, (csPhaseEndMs - now + 999) / 1000);
            Ui.centered(batch, Ui.fontTitle, String.valueOf(remain), 768, 612,
                new Color(1f, 0.6f, 0.25f, 1f));
        }
        // xúc xắc
        if (bcDiceRegions != null) {
            for (int i = 0; i < 3; i++) {
                int frame;
                if (csDiceRolling) {
                    int idx = (int) ((now - csDiceRollStart) / 110) % 8;
                    frame = BC_DICE_SEQ[i][idx];
                } else if (csDice[i] >= 0) {
                    frame = csDice[i];
                } else {
                    frame = i;
                }
                batch.draw(bcDiceRegions[frame], 640 + (i - 1) * 76 - 32, 574, 64, 64);
            }
        }
        // lưới 6 ô cửa 3x2
        float gx = 460, cell = 112, pitch = 124;
        for (int d = 0; d < 6; d++) {
            int col = d % 3, row = d / 3;
            float cx = gx + col * pitch;
            float cy = (row == 0) ? 442 : 318;
            boolean hot = (csPhase == 2 && csTaFrom == d)
                || (csPhase == 1 && !csBetLocked && csMySeat > 0);
            batch.draw(Ui.roundedRect((int) cell, (int) cell, 14,
                new Color(0.10f, 0.16f, 0.24f, 0.97f),
                hot && csTaFrom == d ? new Color(1f, 0.62f, 0.15f, 0.95f) : GLASS_RIM),
                cx, cy);
            if (bcDoorRegions != null) {
                batch.draw(bcDoorRegions[d], cx + 16, cy + 24, 80, 80);
            }
            Ui.centered(batch, Ui.fontSmall, BC_DOORS[d], cx + cell / 2f, cy + 18,
                Color.WHITE);
            int total = csDoorTotal(d);
            if (total > 0) {
                batch.draw(Ui.roundedRect(38, 24, 10,
                    new Color(0.95f, 0.55f, 0.12f, 0.95f), GLASS_RIM),
                    cx + cell - 44, cy + cell - 30);
                Ui.centered(batch, Ui.fontTiny, "×" + total, cx + cell - 25,
                    cy + cell - 13, Color.WHITE);
            }
            if (csPhase == 2 && csMySeat > 0 && csBetsSv[csMySeat][d] > 0) {
                Ui.fontTiny.setColor(1f, 0.85f, 0.38f, 1f);
                Ui.fontTiny.draw(batch, "của bạn", cx + 6, cy + cell - 10);
            }
        }
        // 5 ghế
        for (int s = 0; s < 5; s++) {
            CsSeat seat = csSeats[s];
            float[] pos = csSeatPos(s);
            if (seat.id == -1 || seat.doll == null) {
                Ui.centered(batch, Ui.fontTiny, "Ghế trống", pos[0], pos[1] + 52,
                    new Color(1f, 1f, 1f, 0.4f));
                continue;
            }
            game.dollRenderer.draw(batch, seat.doll, seat.anim.frameIndex(),
                pos[0], pos[1], 2f, false);
            boolean isOwner = seat.id == csOwnerId;
            Ui.centered(batch, Ui.fontSmall, truncTo(Ui.fontSmall, seat.name, 130),
                pos[0], pos[1] - 12,
                isOwner ? new Color(1f, 0.85f, 0.38f, 1f) : Color.WHITE);
            Ui.centered(batch, Ui.fontTiny, fmtMoney(seat.xu) + " xu",
                pos[0], pos[1] - 36, new Color(1f, 1f, 1f, 0.7f));
            if (csPhase == 0 && seat.ready) {
                Ui.centered(batch, Ui.fontTiny, "Sẵn sàng", pos[0], pos[1] - 60,
                    new Color(0.45f, 0.95f, 0.5f, 1f));
            }
            if (csPhase > 0) {
                int bet = 0;
                for (int d = 0; d < 6; d++) bet += csBetsSv[s][d];
                if (s == csMySeat && csPhase == 1 && !csBetLocked) {
                    for (int d = 0; d < 6; d++) bet += csMyBets[d];
                }
                if (bet > 0) {
                    Ui.centered(batch, Ui.fontTiny, "Đã đặt " + bet + " đơn vị",
                        pos[0], pos[1] - 60, new Color(1f, 0.8f, 0.45f, 1f));
                }
            }
            if (csFinished && csDeltas[s] != 0) {
                // bong bóng delta nằm DƯỚI dòng "Đã đặt" của ghế (vị trí cũ
                // trên đầu ghế đè vào tiêu đề panel/lưới cửa — chụp kiểm
                // chứng 2026-11-04)
                Ui.centered(batch, Ui.font,
                    (csDeltas[s] > 0 ? "+" : "-") + fmtMoney(Math.abs(csDeltas[s])),
                    pos[0], pos[1] - 84,
                    csDeltas[s] > 0 ? new Color(0.45f, 0.95f, 0.5f, 1f)
                        : new Color(1f, 0.45f, 0.4f, 1f));
            }
        }
        // tiền bay (gói 60)
        for (int i = csFlies.size() - 1; i >= 0; i--) {
            CsFly f = csFlies.get(i);
            float t = (now - f.startMs) / 900f;
            if (t >= 1f) {
                csFlies.remove(i);
                continue;
            }
            if (f.from < 0 || f.from > 4 || f.to < 0 || f.to > 4) continue;
            float[] a = csSeatPos(f.from), b = csSeatPos(f.to);
            float fx = a[0] + (b[0] - a[0]) * t;
            float fy = a[1] + 60 + (b[1] - a[1]) * t + (float) (Math.sin(t * Math.PI) * 40);
            Ui.centered(batch, Ui.fontSmall, "+" + fmtMoney(f.amount), fx, fy,
                new Color(1f, 0.9f, 0.4f, 1f - t * 0.5f));
        }
        // gợi ý + thanh nút theo pha
        String hint = csHintText();
        if (!hint.isEmpty()) {
            Ui.centered(batch, Ui.fontSmall, hint, 640, 100,
                new Color(1f, 1f, 1f, 0.85f));
        }
        csButton(CS_PX + CS_PW - 174, 20, 150, 52, "Rời bàn", 2);
        if (csFinished) {
            csButton(540, 20, 200, 52, "Tiếp tục", 1);
        } else if (csPhase == 0) {
            if (csMySeat == 0) {
                csButton(462, 20, 170, 52, "Đặt tiền", 0);
                csButton(646, 20, 170, 52, "Bắt đầu", 1);
            } else if (csMySeat > 0) {
                boolean ready = csSeats[csMySeat].ready;
                csButton(530, 20, 220, 52, ready ? "Huỷ sẵn sàng" : "Sẵn sàng", ready ? 0 : 1);
            }
        } else if (csPhase == 1 && csMySeat > 0 && !csBetLocked) {
            csButton(485, 20, 150, 52, "Đặt lại", 0);
            csButton(645, 20, 150, 52, "Xong", 1);
        } else if (csPhase == 2 && csTurnSeat == csMySeat && csMySeat > 0) {
            if (csTaFrom >= 0) {
                csButton(471, 20, 160, 52, "Bỏ lượt", 0);
                csButton(645, 20, 160, 52, "Chọn lại", 0);
            } else {
                csButton(555, 20, 170, 52, "Bỏ lượt", 0);
            }
        }
    }

    // ---------- Tiến Lên: vẽ bàn + chạm ----------

    /** Vị trí ghế theo rel (0 mình · 1 phải · 2 trên · 3 trái). */
    private float[] tlSeatPos(int seat) {
        int rel = csMySeat >= 0 ? (seat - csMySeat + 4) % 4 : seat;
        switch (rel) {
            case 0: return new float[]{215, 235};
            case 1: return new float[]{1090, 395};
            case 2: return new float[]{640, 592};
            default: return new float[]{190, 395};
        }
    }

    private void drawTlBoard() {
        CsSeat owner = csOwnerId >= 0 ? csSeatById(csOwnerId) : null;
        String sub = "Chủ bàn: " + (owner != null ? owner.name : "—")
            + (csBoardMoney > 0 ? " · Mức: " + fmtMoney(csBoardMoney) + " xu"
                : " · Chưa đặt mức");
        csPanelBase("Tiến Lên — Bàn " + (csBoardId + 1), sub);
        long now = System.currentTimeMillis();
        int myId = ownId();
        boolean myTurn = tlPlaying && tlTurnId == myId && !tlResults.containsKey(myId);

        // trạng thái: đặt ở vùng giữa trống (tránh ghế trên cùng ở 640,592)
        if (!tlStatus.isEmpty()) {
            Ui.centered(batch, Ui.font, tlStatus, 640, 292,
                new Color(1f, 0.85f, 0.38f, 1f));
        }

        // 4 ghế
        for (int s = 0; s < 4; s++) {
            CsSeat seat = csSeats[s];
            float[] pos = tlSeatPos(s);
            if (seat.id == -1 || seat.doll == null) {
                Ui.centered(batch, Ui.fontTiny, "Ghế trống", pos[0], pos[1] + 52,
                    new Color(1f, 1f, 1f, 0.4f));
                continue;
            }
            boolean isTurn = tlPlaying && seat.id == tlTurnId;
            if (isTurn) {
                batch.draw(Ui.roundedRect(120, 168, 14,
                    new Color(1f, 0.62f, 0.15f, 0.18f),
                    new Color(1f, 0.62f, 0.15f, 0.95f)),
                    pos[0] - 60, pos[1] - 66);
            }
            game.dollRenderer.draw(batch, seat.doll, seat.anim.frameIndex(),
                pos[0], pos[1], 2f, false);
            boolean isOwner = seat.id == csOwnerId;
            Ui.centered(batch, Ui.fontSmall, truncTo(Ui.fontSmall, seat.name, 130),
                pos[0], pos[1] - 12,
                isOwner ? new Color(1f, 0.85f, 0.38f, 1f) : Color.WHITE);
            Ui.centered(batch, Ui.fontTiny, fmtMoney(seat.xu) + " xu",
                pos[0], pos[1] - 36, new Color(1f, 1f, 1f, 0.7f));
            int[] res = tlResults.get(seat.id);
            if (res != null) {
                Ui.centered(batch, Ui.fontSmall, "Về " + (res[0] + 1),
                    pos[0], pos[1] - 62, new Color(1f, 0.85f, 0.38f, 1f));
                if (res[1] != 0) {
                    Ui.centered(batch, Ui.fontSmall,
                        (res[1] > 0 ? "+" : "-") + fmtMoney(Math.abs(res[1])),
                        pos[0], pos[1] - 88,
                        res[1] > 0 ? new Color(0.45f, 0.95f, 0.5f, 1f)
                            : new Color(1f, 0.45f, 0.4f, 1f));
                }
            } else if (!tlPlaying && !tlStopped && seat.ready) {
                Ui.centered(batch, Ui.fontTiny, "Sẵn sàng", pos[0], pos[1] - 60,
                    new Color(0.45f, 0.95f, 0.5f, 1f));
            }
            // bài úp của đối thủ
            if (seat.id != myId && tlPlaying && tlCounts[s] > 0) {
                int n = tlCounts[s];
                int rel = csMySeat >= 0 ? (s - csMySeat + 4) % 4 : s;
                if (rel == 2) {
                    float tw = 26 + Math.min(n, 8) * 12f;
                    for (int i = 0; i < Math.min(n, 8); i++) {
                        drawCard(pos[0] - tw / 2f + i * 12f, pos[1] - 118, 26, 35, -1);
                    }
                } else {
                    for (int i = 0; i < Math.min(n, 5); i++) {
                        drawCard(pos[0] - 13 + (rel == 1 ? 52 : -78), pos[1] - 20 + i * 7f,
                            26, 35, -1);
                    }
                }
                Ui.centered(batch, Ui.fontSmall, "×" + n,
                    pos[0] + (rel == 1 ? 66 : rel == 3 ? -66 : 0),
                    pos[1] + (rel == 2 ? -96 : 24),
                    new Color(1f, 0.85f, 0.38f, 1f));
            }
        }

        // giữa bàn: kết quả / bài lộ / bài trên bàn / chờ
        if (tlStopped && !tlResults.isEmpty()) {
            batch.draw(Ui.roundedRect(480, 250, 16, GLASS_FILL_DARK, GLASS_RIM),
                400, 224);
            Ui.centered(batch, Ui.font, "Kết quả ván", 640, 448,
                new Color(1f, 0.85f, 0.38f, 1f));
            java.util.List<java.util.Map.Entry<Integer, int[]>> rows =
                new ArrayList<>(tlResults.entrySet());
            rows.sort((a, b) -> Integer.compare(a.getValue()[0], b.getValue()[0]));
            float ry = 406;
            for (java.util.Map.Entry<Integer, int[]> e : rows) {
                CsSeat seat = csSeatById(e.getKey());
                String nm = seat != null ? seat.name : ("#" + e.getKey());
                int d = e.getValue()[1];
                Ui.font.draw(batch, (e.getValue()[0] + 1) + ". " + truncTo(Ui.font, nm, 220),
                    436, ry);
                String dtxt = (d > 0 ? "+" : d < 0 ? "-" : "") + fmtMoney(Math.abs(d)) + " xu";
                layout.setText(Ui.font, dtxt);
                float dw = layout.width;
                Ui.font.setColor(d > 0 ? 0.45f : d < 0 ? 1f : 1f,
                    d > 0 ? 0.95f : d < 0 ? 0.45f : 1f,
                    d > 0 ? 0.5f : d < 0 ? 0.4f : 1f, 1f);
                Ui.font.draw(batch, dtxt, 844 - dw, ry);
                Ui.font.setColor(Color.WHITE);
                ry -= 44;
            }
        } else if (!tlShown.isEmpty()) {
            CsSeat sh = tlShownId >= 0 ? csSeatById(tlShownId) : null;
            Ui.centered(batch, Ui.fontSmall,
                sh != null ? "Bài của " + sh.name : "Bài lộ", 640, 452, Color.WHITE);
            float cw = 46, step = 30;
            float total = cw + (tlShown.size() - 1) * step;
            for (int i = 0; i < tlShown.size(); i++) {
                drawCard(640 - total / 2f + i * step, 372, cw, 62, tlShown.get(i));
            }
        } else if (tlPlaying) {
            if (!tlTable.isEmpty()) {
                CsSeat tp = tlTableSeat >= 0 ? csSeats[tlTableSeat] : null;
                if (tp != null) {
                    Ui.centered(batch, Ui.fontSmall, tp.name + " vừa đánh", 640, 452,
                        new Color(1f, 1f, 1f, 0.75f));
                }
                float cw = 46, step = 30;
                float total = cw + (tlTable.size() - 1) * step;
                for (int i = 0; i < tlTable.size(); i++) {
                    drawCard(640 - total / 2f + i * step, 372, cw, 62, tlTable.get(i));
                }
            } else {
                CsSeat tp = tlTurnId >= 0 ? csSeatById(tlTurnId) : null;
                Ui.centered(batch, Ui.fontSmall,
                    tlTurnId == myId ? "Vòng mới — bạn dẫn, đánh bất kỳ tổ hợp nào"
                        : "Vòng mới — chờ " + (tp != null ? tp.name : "…") + " dẫn",
                    640, 420, new Color(1f, 1f, 1f, 0.75f));
            }
            long remain = Math.max(0, (tlTurnEndMs - now + 999) / 1000);
            Ui.centered(batch, Ui.fontTitle, String.valueOf(remain), 640, 332,
                remain <= 10 ? new Color(1f, 0.45f, 0.4f, 1f)
                    : new Color(1f, 0.85f, 0.38f, 1f));
            if (myTurn) {
                Ui.centered(batch, Ui.fontSmall, "Tới lượt bạn — chọn bài rồi bấm Đánh",
                    640, 168, new Color(0.45f, 0.95f, 0.5f, 1f));
            }
        } else if (!tlStopped) {
            Ui.centered(batch, Ui.font,
                csMySeat == 0 ? "Bấm Bắt đầu khi mọi người đã sẵn sàng"
                    : "Chờ chủ bàn bắt đầu ván mới…",
                640, 400, new Color(1f, 1f, 1f, 0.8f));
        }

        // bài của mình (quạt dưới đáy)
        if (!tlHand.isEmpty()) {
            float step = 36;
            float total = 56 + (tlHand.size() - 1) * step;
            float x0 = 640 - total / 2f;
            for (int i = 0; i < tlHand.size(); i++) {
                int c = tlHand.get(i);
                float y = 30 + (tlSel.contains(c) ? 18 : 0);
                drawCard(x0 + i * step, y, 56, 76, c);
            }
        }

        // thanh nút
        csButton(CS_PX + CS_PW - 174, 20, 150, 52, "Rời bàn", 2);
        if (tlStopped) {
            csButton(540, 20, 200, 52, "Chơi tiếp", 1);
        } else if (tlPlaying) {
            if (myTurn) {
                csButton(856, 118, 160, 52, "Đánh", tlSel.isEmpty() ? 3 : 1);
                csButton(1032, 118, 160, 52, "Bỏ lượt", tlTable.isEmpty() ? 3 : 0);
            }
        } else if (csMySeat == 0) {
            csButton(462, 20, 170, 52, "Đặt mức", 0);
            csButton(646, 20, 170, 52, "Bắt đầu", 1);
        } else if (csMySeat > 0) {
            boolean ready = csSeats[csMySeat].ready;
            csButton(530, 20, 220, 52, ready ? "Huỷ sẵn sàng" : "Sẵn sàng", ready ? 0 : 1);
        }
    }

    private void tlTouch(float x, float y) {
        int myId = ownId();
        if (tlStopped) {
            if (x >= 540 && x <= 740 && y >= 20 && y <= 72) {
                tlReset();
                for (CsSeat seat : csSeats) seat.ready = false;
            }
            return;
        }
        if (tlPlaying && tlTurnId == myId && !tlResults.containsKey(myId)) {
            // chọn bài
            if (!tlHand.isEmpty()) {
                float step = 36;
                float total = 56 + (tlHand.size() - 1) * step;
                float x0 = 640 - total / 2f;
                for (int i = tlHand.size() - 1; i >= 0; i--) {
                    int c = tlHand.get(i);
                    float cy = 30 + (tlSel.contains(c) ? 18 : 0);
                    if (x >= x0 + i * step && x <= x0 + i * step + 56
                            && y >= cy && y <= cy + 76) {
                        if (tlSel.contains(c)) tlSel.remove(c); else tlSel.add(c);
                        return;
                    }
                }
            }
            if (x >= 856 && x <= 1016 && y >= 118 && y <= 170) {
                if (tlSel.isEmpty()) return;
                if (tlMustInclude0 && !tlSel.contains(0)) {
                    tlStatus = "Nước đầu phải có lá 3 bích";
                    return;
                }
                java.util.List<Integer> cards = new ArrayList<>(tlSel);
                java.util.Collections.sort(cards);
                Msg mv = csMsgRB(CS_BET_OK);
                try {
                    mv.writer().writeByte(cards.size());
                    for (int c : cards) mv.writer().writeByte(c);
                } catch (Exception ignored) {
                }
                csSend(mv);
                return;
            }
            if (x >= 1032 && x <= 1192 && y >= 118 && y <= 170) {
                if (!tlTable.isEmpty()) csSend(csMsgRB(CS_SKIP));
                return;
            }
            return;
        }
        if (!tlPlaying) {
            if (csMySeat == 0) {
                if (x >= 462 && x <= 632 && y >= 20 && y <= 72) {
                    csMoneySheet = true;
                    return;
                }
                if (x >= 646 && x <= 816 && y >= 20 && y <= 72) {
                    csSend(csMsgRB(CS_START));
                    return;
                }
            } else if (csMySeat > 0) {
                if (x >= 530 && x <= 750 && y >= 20 && y <= 72) {
                    Msg rd = csMsgRB(CS_READY);
                    try {
                        rd.writer().writeBoolean(!csSeats[csMySeat].ready);
                    } catch (Exception ignored) {
                    }
                    csSend(rd);
                }
            }
        }
    }

    private void drawPhomBoard() {
        CsSeat owner = csOwnerId >= 0 ? csSeatById(csOwnerId) : null;
        String sub = "Chủ bàn: " + (owner != null ? owner.name : "—")
            + (csBoardMoney > 0 ? " · Mức: " + fmtMoney(csBoardMoney) + " xu"
                : " · Chưa đặt mức");
        csPanelBase("Phỏm — Bàn " + (csBoardId + 1), sub);
        long now = System.currentTimeMillis();
        int myId = ownId();
        boolean myTurn = phPlaying && phTurnId == myId;
        boolean needHa = myTurn && phPhase == 1 && phMyFires >= 3 && !phHaDone;

        if (!phStatus.isEmpty()) {
            Ui.centered(batch, Ui.font, phStatus, 640, 292,
                new Color(1f, 0.85f, 0.38f, 1f));
        }

        // gợi ý phỏm trên tay mình (phân hoạch tốt nhất) để tô viền
        java.util.Set<Integer> hintMeld = new java.util.HashSet<>();
        if (phPlaying && myTurn && phPhase == 1) {
            java.util.List<Integer> free = new ArrayList<>();
            for (int c : phHand) if (!phLocked.contains(c)) free.add(c);
            for (java.util.List<Integer> g : phPartition(free).melds) {
                hintMeld.addAll(g);
            }
        }

        // 4 ghế
        for (int s = 0; s < 4; s++) {
            CsSeat seat = csSeats[s];
            float[] pos = tlSeatPos(s);
            if (seat.id == -1 || seat.doll == null) {
                Ui.centered(batch, Ui.fontTiny, "Ghế trống", pos[0], pos[1] + 52,
                    new Color(1f, 1f, 1f, 0.4f));
                continue;
            }
            boolean isTurn = phPlaying && seat.id == phTurnId;
            if (isTurn) {
                batch.draw(Ui.roundedRect(120, 168, 14,
                    new Color(1f, 0.62f, 0.15f, 0.18f),
                    new Color(1f, 0.62f, 0.15f, 0.95f)),
                    pos[0] - 60, pos[1] - 66);
            }
            game.dollRenderer.draw(batch, seat.doll, seat.anim.frameIndex(),
                pos[0], pos[1], 2f, false);
            boolean isOwner = seat.id == csOwnerId;
            Ui.centered(batch, Ui.fontSmall, truncTo(Ui.fontSmall, seat.name, 130),
                pos[0], pos[1] - 12,
                isOwner ? new Color(1f, 0.85f, 0.38f, 1f) : Color.WHITE);
            Ui.centered(batch, Ui.fontTiny, fmtMoney(seat.xu) + " xu",
                pos[0], pos[1] - 36, new Color(1f, 1f, 1f, 0.7f));
            int[] res = phResults.get(seat.id);
            if (res != null) {
                String lab = res[0] == -2 ? "Cháy" : res[0] == -1 ? "Ù"
                    : res[0] + " điểm";
                Ui.centered(batch, Ui.fontSmall, lab, pos[0], pos[1] - 62,
                    new Color(1f, 0.85f, 0.38f, 1f));
                if (res[1] != 0) {
                    Ui.centered(batch, Ui.fontSmall,
                        (res[1] > 0 ? "+" : "-") + fmtMoney(Math.abs(res[1])),
                        pos[0], pos[1] - 88,
                        res[1] > 0 ? new Color(0.45f, 0.95f, 0.5f, 1f)
                            : new Color(1f, 0.45f, 0.4f, 1f));
                }
            } else if (!phPlaying && !phStopped && seat.ready) {
                Ui.centered(batch, Ui.fontTiny, "Sẵn sàng", pos[0], pos[1] - 60,
                    new Color(0.45f, 0.95f, 0.5f, 1f));
            }
            // phỏm đã ăn/hạ: hàng lá nhỏ dưới tên ghế (chỉ khi đang chơi —
            // hết ván nhãn kết quả ở cùng vị trí, tránh vẽ đè)
            java.util.List<Integer> melds = phMelds.get(s);
            if (!melds.isEmpty() && phPlaying) {
                float mw = 26f, mstep = 15f;
                float mtotal = mw + (melds.size() - 1) * mstep;
                for (int i = 0; i < melds.size(); i++) {
                    drawPhomCard(pos[0] - mtotal / 2f + i * mstep, pos[1] - 132,
                        mw, 35, melds.get(i));
                }
            }
            // bài úp của đối thủ
            if (seat.id != myId && phPlaying && phCounts[s] > 0) {
                int n = phCounts[s];
                int rel = csMySeat >= 0 ? (s - csMySeat + 4) % 4 : s;
                if (rel == 2) {
                    float shift = melds.isEmpty() ? 0 : 150; // tránh hàng phỏm đã hạ
                    float tw = 26 + Math.min(n, 8) * 12f;
                    for (int i = 0; i < Math.min(n, 8); i++) {
                        drawCard(pos[0] + shift - tw / 2f + i * 12f, pos[1] - 118, 26, 35, -1);
                    }
                    Ui.centered(batch, Ui.fontSmall, "×" + n,
                        pos[0] + shift, pos[1] - 96,
                        new Color(1f, 0.85f, 0.38f, 1f));
                } else {
                    for (int i = 0; i < Math.min(n, 5); i++) {
                        drawCard(pos[0] - 13 + (rel == 1 ? 52 : -78), pos[1] - 20 + i * 7f,
                            26, 35, -1);
                    }
                    Ui.centered(batch, Ui.fontSmall, "×" + n,
                        pos[0] + (rel == 1 ? 66 : -66), pos[1] + 24,
                        new Color(1f, 0.85f, 0.38f, 1f));
                }
            }
        }

        // giữa bàn: kết quả / lá trên bàn / chờ
        if (phStopped && !phResults.isEmpty()) {
            batch.draw(Ui.roundedRect(480, 250, 16, GLASS_FILL_DARK, GLASS_RIM),
                400, 224);
            Ui.centered(batch, Ui.font,
                phBanner.isEmpty() ? "Kết quả ván" : phBanner, 640, 448,
                new Color(1f, 0.85f, 0.38f, 1f));
            float ry = 406;
            for (int s = 0; s < 4; s++) {
                CsSeat seat = csSeats[s];
                if (seat.id == -1) continue;
                int[] res = phResults.get(seat.id);
                if (res == null) continue;
                String lab = res[0] == -2 ? "Cháy" : res[0] == -1 ? "Ù"
                    : res[0] + " điểm";
                Ui.font.draw(batch, truncTo(Ui.font, seat.name, 200) + " — " + lab,
                    436, ry);
                int d = res[1];
                String dtxt = (d > 0 ? "+" : d < 0 ? "-" : "") + fmtMoney(Math.abs(d)) + " xu";
                layout.setText(Ui.font, dtxt);
                Ui.font.setColor(d > 0 ? 0.45f : d < 0 ? 1f : 1f,
                    d > 0 ? 0.95f : d < 0 ? 0.45f : 1f,
                    d > 0 ? 0.5f : d < 0 ? 0.4f : 1f, 1f);
                Ui.font.draw(batch, dtxt, 844 - layout.width, ry);
                Ui.font.setColor(Color.WHITE);
                ry -= 44;
            }
        } else if (phPlaying) {
            if (phTableCard >= 0) {
                CsSeat tp = phTableFromSeat >= 0 ? csSeats[phTableFromSeat] : null;
                if (tp != null) {
                    Ui.centered(batch, Ui.fontSmall, tp.name + " vừa đánh", 640, 452,
                        new Color(1f, 1f, 1f, 0.75f));
                }
                drawPhomCard(640 - 23, 372, 46, 62, phTableCard);
            } else {
                CsSeat tp = phTurnId >= 0 ? csSeatById(phTurnId) : null;
                Ui.centered(batch, Ui.fontSmall,
                    phTurnId == myId ? "Bạn đi trước — bốc bài rồi đánh"
                        : "Chờ " + (tp != null ? tp.name : "…"),
                    640, 420, new Color(1f, 1f, 1f, 0.75f));
            }
            long remain = Math.max(0, (phTurnEndMs - now + 999) / 1000);
            Ui.centered(batch, Ui.fontTitle, String.valueOf(remain), 640, 332,
                remain <= 10 ? new Color(1f, 0.45f, 0.4f, 1f)
                    : new Color(1f, 0.85f, 0.38f, 1f));
            if (myTurn) {
                Ui.centered(batch, Ui.fontSmall,
                    phPhase == 0 ? "Tới lượt bạn — Ăn lá trên bàn hoặc Bốc bài"
                        : needHa ? "Lượt cuối — Hạ phỏm rồi đánh lá cuối"
                        : "Chọn 1 lá rồi bấm Đánh",
                    640, 168, new Color(0.45f, 0.95f, 0.5f, 1f));
            }
        } else if (!phStopped) {
            Ui.centered(batch, Ui.font,
                csMySeat == 0 ? "Bấm Bắt đầu khi mọi người đã sẵn sàng"
                    : "Chờ chủ bàn bắt đầu ván mới…",
                640, 400, new Color(1f, 1f, 1f, 0.8f));
        }

        // bài của mình (quạt dưới đáy)
        if (!phHand.isEmpty()) {
            float step = 36;
            float total = 56 + (phHand.size() - 1) * step;
            float x0 = 640 - total / 2f;
            for (int i = 0; i < phHand.size(); i++) {
                int c = phHand.get(i);
                float y = 30 + (phSel.contains(c) ? 18 : 0);
                if (hintMeld.contains(c)) {
                    batch.draw(Ui.roundedRect(60, 80, 6,
                        new Color(1f, 0.85f, 0.38f, 0.10f),
                        new Color(1f, 0.85f, 0.38f, 0.9f)),
                        x0 + i * step - 2, y - 2);
                }
                drawPhomCard(x0 + i * step, y, 56, 76, c);
                if (phLocked.contains(c)) {
                    batch.draw(Ui.roundedRect(56, 5, 2,
                        new Color(1f, 0.85f, 0.38f, 1f), null), x0 + i * step, y);
                }
            }
        }

        // thanh nút
        csButton(CS_PX + CS_PW - 174, 20, 150, 52, "Rời bàn", 2);
        if (phStopped) {
            csButton(540, 20, 200, 52, "Chơi tiếp", 1);
        } else if (phPlaying) {
            if (myTurn && phPhase == 0) {
                boolean canEat = phSelEats() || phFindEat() != null;
                csButton(856, 118, 160, 52, "Ăn", canEat ? 1 : 3);
                csButton(1032, 118, 160, 52, "Bốc", 0);
            } else if (myTurn && phPhase == 1) {
                if (needHa) {
                    csButton(856, 118, 160, 52, "Hạ phỏm", 1);
                    csButton(1032, 118, 160, 52, "Đánh", 3);
                } else {
                    boolean one = phSel.size() == 1
                        && !phLocked.contains(phSel.iterator().next());
                    csButton(856, 118, 160, 52, "Đánh", one ? 1 : 3);
                }
            }
        } else if (csMySeat == 0) {
            csButton(462, 20, 170, 52, "Đặt mức", 0);
            csButton(646, 20, 170, 52, "Bắt đầu", 1);
        } else if (csMySeat > 0) {
            boolean ready = csSeats[csMySeat].ready;
            csButton(530, 20, 220, 52, ready ? "Huỷ sẵn sàng" : "Sẵn sàng", ready ? 0 : 1);
        }
    }

    private void phomTouch(float x, float y) {
        int myId = ownId();
        if (phStopped) {
            if (x >= 540 && x <= 740 && y >= 20 && y <= 72) {
                phReset();
                for (CsSeat seat : csSeats) seat.ready = false;
            }
            return;
        }
        if (phPlaying && phTurnId == myId) {
            // chọn bài trong quạt
            if (!phHand.isEmpty() && y >= 30 && y <= 124) {
                float step = 36;
                float total = 56 + (phHand.size() - 1) * step;
                float x0 = 640 - total / 2f;
                for (int i = phHand.size() - 1; i >= 0; i--) {
                    int c = phHand.get(i);
                    float cy = 30 + (phSel.contains(c) ? 18 : 0);
                    if (x >= x0 + i * step && x <= x0 + i * step + 56
                            && y >= cy && y <= cy + 76) {
                        if (phPhase == 1) phSel.clear();
                        if (phSel.contains(c)) phSel.remove(c);
                        else if (phSel.size() < 3) phSel.add(c);
                        return;
                    }
                }
            }
            if (phPhase == 0) {
                if (x >= 856 && x <= 1016 && y >= 118 && y <= 170) { // Ăn
                    java.util.List<Integer> group = phSelEats()
                        ? new ArrayList<>(phSel) : phFindEat();
                    if (group == null) {
                        phStatus = "Chọn 2–3 lá tạo phỏm với lá trên bàn để Ăn";
                        return;
                    }
                    java.util.Collections.sort(group);
                    phPendingEat = group;
                    Msg e = csMsgRB(CS_EAT_CARD);
                    try {
                        for (int c : group) e.writer().writeByte(c);
                        e.writer().writeByte(0); // index (server bỏ qua)
                    } catch (Exception ignored) {
                    }
                    csSend(e);
                    return;
                }
                if (x >= 1032 && x <= 1192 && y >= 118 && y <= 170) { // Bốc
                    csSend(csMsgRB(CS_GET_CARD));
                    return;
                }
                return;
            }
            // phase 1
            boolean needHa = phMyFires >= 3 && !phHaDone;
            if (x >= 856 && x <= 1016 && y >= 118 && y <= 170) {
                if (needHa) { // Hạ phỏm theo phân hoạch tốt nhất
                    java.util.List<Integer> free = new ArrayList<>();
                    for (int c : phHand) if (!phLocked.contains(c)) free.add(c);
                    java.util.List<java.util.List<Integer>> melds =
                        phPartition(free).melds;
                    Msg hm = csMsgRB(CS_TA);
                    try {
                        for (int gi = 0; gi < melds.size(); gi++) {
                            if (gi > 0) hm.writer().writeByte(-1);
                            for (int c : melds.get(gi)) hm.writer().writeByte(c);
                        }
                    } catch (Exception ignored) {
                    }
                    csSend(hm);
                } else if (phSel.size() == 1) { // Đánh
                    int card = phSel.iterator().next();
                    if (phLocked.contains(card)) {
                        phStatus = "Lá thuộc phỏm đã ăn — không đánh được";
                        return;
                    }
                    Msg fm = csMsgRB(CS_BET_OK);
                    try {
                        fm.writer().writeByte(card);
                    } catch (Exception ignored) {
                    }
                    csSend(fm);
                }
                return;
            }
            return;
        }
        if (!phPlaying) {
            if (csMySeat == 0) {
                if (x >= 462 && x <= 632 && y >= 20 && y <= 72) {
                    csMoneySheet = true;
                    return;
                }
                if (x >= 646 && x <= 816 && y >= 20 && y <= 72) {
                    csSend(csMsgRB(CS_START));
                    return;
                }
            } else if (csMySeat > 0) {
                if (x >= 530 && x <= 750 && y >= 20 && y <= 72) {
                    Msg rd = csMsgRB(CS_READY);
                    try {
                        rd.writer().writeBoolean(!csSeats[csMySeat].ready);
                    } catch (Exception ignored) {
                    }
                    csSend(rd);
                }
            }
        }
    }

    private String csHintText() {
        if (csSpectating && !csFinished) return csStatus;
        if (csFinished) {
            if (csMySeat >= 0) {
                int d = csDeltas[csMySeat];
                return d > 0 ? "Ván này bạn thắng " + fmtMoney(d) + " xu."
                    : d < 0 ? "Ván này bạn thua " + fmtMoney(-d) + " xu."
                    : "Ván này bạn hoà vốn.";
            }
            return "";
        }
        if (csPhase == 0) {
            return csMySeat == 0
                ? "Bạn là chủ bàn — đặt mức tiền, chờ người chơi sẵn sàng rồi bấm Bắt đầu."
                : "Chờ chủ bàn bắt đầu — bấm Sẵn sàng khi đã sẵn lòng.";
        }
        if (csPhase == 1) {
            if (csMySeat == 0) return "Bạn là chủ bàn — chờ người chơi đặt cược.";
            if (csBetLocked) return "Đã chốt cược — chờ mọi người…";
            int sum = 0;
            for (int v : csMyBets) sum += v;
            return "Chạm vào ô cửa để đặt — đã đặt " + sum + "/6 đơn vị"
                + (csBoardMoney > 0 ? " (mỗi đơn vị " + fmtMoney(csBoardMoney) + " xu)" : "");
        }
        if (csPhase == 2) {
            if (csTurnSeat == csMySeat && csMySeat > 0) {
                return csTaFrom < 0
                    ? "Lượt tả của bạn: chạm ô có tiền của bạn để chọn dời đi."
                    : "Đã chọn ô " + BC_DOORS[csTaFrom] + " — chạm ô đích để dời sang.";
            }
            if (csTurnSeat >= 0 && csSeats[csTurnSeat].id != -1) {
                return csSeats[csTurnSeat].name + " đang tả…";
            }
            return "Đang chờ lượt tả…";
        }
        if (csPhase == 3) return "Đang mở xúc xắc…";
        return "";
    }

