    private void openMiniGameHub() {
        if (!online()) {
            addChatLog(TAB_SYSTEM, null,
                "Mini game cần chơi online — bản chơi thử không có.", true);
            return;
        }
        closeOtherPanels();
        mgOpen = true;
        mgZone = 0;
        mgPage = mgInRoom ? 1 : 0;
        mgScroll = 0f;
        mgStatus = "";
        mgRequestList();
    }

    private void mgRequestList() {
        try { AvatarProtocol.mgList(game.connection); } catch (Exception ignored) { }
    }

    private void mgCloseHub() {
        if (mgInRoom || mgWaiting) {
            try { AvatarProtocol.mgLeave(game.connection); } catch (Exception ignored) { }
        }
        mgInRoom = false;
        mgWaiting = false;
        mgRoomId = -1;
        mgOpen = false;
    }

    private void mgJoinRoom(MgRoom r) {
        if (r == null) return;
        try { AvatarProtocol.mgJoin(game.connection, r.id); } catch (Exception ignored) { }
    }

    private void mgWatchRoom(MgRoom r) {
        if (r == null) return;
        try { AvatarProtocol.mgWatch(game.connection, r.id); } catch (Exception ignored) { }
    }

    private void mgInviteFriend(FriendEntry f) {
        if (f == null) return;
        try {
            AvatarProtocol.mgInvite(game.connection, f.id, mgGame);
            mgStatus = "Đã gửi lời mời tới " + f.name + " — chờ bạn ấy trả lời.";
            mgPage = 1;
        } catch (Exception ignored) { }
    }

    private float mgMaxScroll() {
        int n = mgPage == 2 ? friends.size()
            : mgPage == 3 ? mgTopRows.size() : mgRoomsShown.size();
        return Math.max(0f, n * 62f - (mgPage == 3 ? 352f : 404f));
    }

    // ----- Gói hub/Tàu Chiến (cmd −113) -----
    private void handleMiniGamePacket(Msg m) {
        try {
            java.io.DataInputStream r = m.reader();
            int gameId = r.readByte();
            int sub = r.readByte();
            if (gameId == 0) {
                switch (sub) {
                    case AvatarProtocol.MG_S_LIST: {
                        mgRooms.clear();
                        int n = r.readShort();
                        for (int i = 0; i < n; i++) {
                            MgRoom room = new MgRoom();
                            room.id = r.readInt();
                            room.gameId = r.readByte();
                            room.n1 = r.readUTF();
                            room.n2 = r.readUTF();
                            room.specs = r.readByte();
                            room.priv = r.readBoolean();
                            room.status = r.readByte();
                            mgRooms.add(room);
                        }
                        refreshMgRoomsShown();
                        mgScroll = MathUtils.clamp(mgScroll, 0f, mgMaxScroll());
                        break;
                    }
                    case AvatarProtocol.MG_S_JOINED: {
                        int roomId = r.readInt();
                        int seat = r.readByte();
                        int joinedGame = r.readByte();
                        String opp = r.readUTF();
                        boolean priv = r.readBoolean();
                        String code = r.readUTF();
                        boolean friendly = r.readBoolean();
                        mgRoomId = roomId;
                        mgGame = joinedGame;
                        mgFriendlyRoom = friendly;
                        mgRoomCode = code;
                        mgWinHist.clear();
                        mgEndBanner = 0;
                        if (joinedGame == AvatarProtocol.MG_GAME_CARO) {
                            crSeat = seat;
                            crPhase = 0;
                            crSpecCount = 0;
                            crWinner = -1;
                            java.util.Arrays.fill(crBoard, (byte) 0);
                            java.util.Arrays.fill(crWinMark, false);
                            if (seat == 0) {
                                crName0 = myDisplayName(); crName1 = opp;
                                mgWaiting = opp.isEmpty();
                                mgMyCode = priv || friendly ? code : "";
                            } else if (seat == 1) {
                                crName0 = opp; crName1 = myDisplayName();
                                mgWaiting = false;
                            }
                            if (seat == 2) { mgOpen = false; crOpen = true; mgWaiting = false; }
                            else {
                                mgInRoom = true;
                                mgStatus = mgWaiting
                                    ? "Đã tạo bàn — chờ đối thủ vào chơi."
                                    : "Đã vào bàn Cờ Caro.";
                            }
                        } else if (joinedGame == AvatarProtocol.MG_GAME_TRUCXANH) {
                            txSeat = seat;
                            txPhase = 0;
                            txSpecCount = 0;
                            txWinner = -1;
                            txResetCards();
                            if (seat == 0) {
                                txName0 = myDisplayName(); txName1 = opp;
                                mgWaiting = opp.isEmpty();
                                mgMyCode = priv || friendly ? code : "";
                            } else if (seat == 1) {
                                txName0 = opp; txName1 = myDisplayName();
                                mgWaiting = false;
                            }
                            if (seat == 2) { mgOpen = false; txOpen = true; mgWaiting = false; }
                            else {
                                mgInRoom = true;
                                mgStatus = mgWaiting
                                    ? "Đã tạo bàn — chờ đối thủ vào chơi."
                                    : "Đã vào bàn Trúc Xanh.";
                            }
                        } else if (joinedGame == AvatarProtocol.MG_GAME_SNAKE) {
                            snSeat = seat;
                            snPhase = 0;
                            snSpecCount = 0;
                            snWinner = -1;
                            snPos[0] = snPos[1] = 0;
                            snDice = -1;
                            if (seat == 0) {
                                snName0 = myDisplayName(); snName1 = opp;
                                mgWaiting = opp.isEmpty();
                                mgMyCode = priv || friendly ? code : "";
                            } else if (seat == 1) {
                                snName0 = opp; snName1 = myDisplayName();
                                mgWaiting = false;
                            }
                            if (seat == 2) { mgOpen = false; snOpen = true; mgWaiting = false; }
                            else {
                                mgInRoom = true;
                                mgStatus = mgWaiting
                                    ? "Đã tạo bàn — chờ đối thủ vào chơi."
                                    : "Đã vào bàn Rắn Thang.";
                            }
                        } else if (joinedGame == AvatarProtocol.MG_GAME_AINCRAD) {
                            aiSeat = seat;
                            aiPhase = 0;
                            aiSpecCount = 0;
                            aiWinner = -1;
                            aiFloor[0] = aiFloor[1] = 1;
                            aiGhost[0] = aiGhost[1] = false;
                            aiLastDoor[0] = aiLastDoor[1] = -1;
                            if (seat == 0) {
                                aiName0 = myDisplayName(); aiName1 = opp;
                                mgWaiting = opp.isEmpty();
                                mgMyCode = priv || friendly ? code : "";
                            } else if (seat == 1) {
                                aiName0 = opp; aiName1 = myDisplayName();
                                mgWaiting = false;
                            }
                            if (seat == 2) { mgOpen = false; aiOpen = true; mgWaiting = false; }
                            else {
                                mgInRoom = true;
                                mgStatus = mgWaiting
                                    ? "Đã tạo bàn — chờ đối thủ vào chơi."
                                    : "Đã vào bàn Aincrad.";
                            }
                        } else if (seat == 2) { // khán giả Tàu Chiến: snapshot tới ngay
                            tcSeat = 2;
                            tcPhase = 0;
                            tcSpecCount = 0;
                            mgOpen = false;
                            tcOpen = true;
                        } else {
                            mgInRoom = true;
                            tcSeat = seat;
                            if (seat == 0) {
                                tcName0 = myDisplayName();
                                tcName1 = opp;
                                mgWaiting = opp.isEmpty();
                                mgMyCode = priv || friendly ? code : "";
                            } else {
                                tcName0 = opp;
                                tcName1 = myDisplayName();
                                mgWaiting = false;
                            }
                            mgPage = 1;
                            mgStatus = mgWaiting
                                ? "Đã tạo bàn — chờ đối thủ vào chơi."
                                : "Đã vào bàn, chuẩn bị xếp tàu.";
                        }
                        break;
                    }
                    case AvatarProtocol.MG_S_OPP_JOINED: {
                        String joinedName = r.readUTF();
                        tcName1 = joinedName;
                        crName1 = joinedName;
                        txName1 = joinedName;
                        aiName1 = joinedName;
                        mgWaiting = false;
                        break;
                    }
                    case AvatarProtocol.MG_S_OPP_LEFT: {
                        if (crOpen || txOpen || aiOpen) {
                            // Caro/Trúc Xanh/Aincrad: thoát giữa ván đã có
                            // gói END riêng; OPP_LEFT ở đây = bàn giải tán
                            // (khán giả đang xem hoặc chủ bàn huỷ khi chưa đấu)
                            crOpen = false;
                            txOpen = false;
                            aiOpen = false;
                            mgInRoom = false;
                            mgWaiting = false;
                            mgOpen = true;
                            mgPage = 1;
                            mgStatus = "Bàn đã giải tán.";
                            mgRequestList();
                        } else if (tcOpen && tcPhase == 3) {
                            tcBanner = "Đối thủ đã rời bàn.";
                            mgRematchOffer = false;
                        } else if (tcSeat == 2) { // đang xem mà bàn giải tán
                            tcOpen = false;
                            mgOpen = true;
                            mgPage = 1;
                            mgRequestList();
                        } else if (tcSeat == 0 && tcOpen && tcPhase < 2) {
                            // đối thủ rời trước khi đấu: bàn quay lại chờ
                            tcOpen = false;
                            mgWaiting = true;
                            mgOpen = true;
                            mgPage = 1;
                            mgStatus = "Đối thủ đã rời bàn — bàn đang chờ người mới.";
                        } else if (tcOpen) {
                            tcOpen = false;
                            mgInRoom = false;
                            mgWaiting = false;
                            mgOpen = true;
                            mgPage = 1;
                            mgStatus = "Chủ bàn đã rời — bàn đã giải tán.";
                            mgRequestList();
                        } else if (mgInRoom) {
                            mgInRoom = false;
                            mgWaiting = false;
                            mgStatus = "Bàn đã giải tán.";
                            mgRequestList();
                        }
                        break;
                    }
                    case AvatarProtocol.MG_S_REMATCH_OFFER: {
                        r.readByte();
                        mgRematchOffer = true;
                        tcBanner = "Đối thủ rủ chơi ván mới — bấm «Ván mới» để nhận.";
                        crBanner = tcBanner;
                        txBanner = tcBanner;
                        break;
                    }
                    case AvatarProtocol.MG_S_INVITE_IN: {
                        MgInvite inv = new MgInvite();
                        inv.fromId = r.readInt();
                        inv.fromName = r.readUTF();
                        inv.gameId = r.readByte();
                        mgInviteIn = inv;
                        break;
                    }
                    case AvatarProtocol.MG_S_INVITE_RESULT: {
                        boolean ok = r.readBoolean();
                        String name = r.readUTF();
                        if (!ok) {
                            addChatLog(TAB_SYSTEM, null,
                                name + " đã từ chối lời mời chơi mini game.", true);
                        }
                        break;
                    }
                    case AvatarProtocol.MG_S_TOP: {
                        r.readByte(); // gameId của bảng
                        mgTopRows.clear();
                        int tn = r.readShort();
                        for (int i = 0; i < tn; i++) {
                            MgTopRow row = new MgTopRow();
                            row.name = r.readUTF();
                            row.wins = r.readInt();
                            row.plays = r.readInt();
                            mgTopRows.add(row);
                        }
                        mgTopLoaded = true;
                        mgScroll = MathUtils.clamp(mgScroll, 0f, mgMaxScroll());
                        break;
                    }
                    case AvatarProtocol.MG_S_ERROR: {
                        String text = r.readUTF();
                        mgStatus = text;
                        if (tcOpen) tcBanner = text;
                        if (crOpen) crBanner = text;
                        if (txOpen) txBanner = text;
                        if (snOpen) snBanner = text;
                        addChatLog(TAB_SYSTEM, null, text, true);
                        break;
                    }
                    default: break;
                }
            } else if (gameId == AvatarProtocol.MG_GAME_TAUCHIEN) {
                handleTcPacket(sub, r);
            } else if (gameId == AvatarProtocol.MG_GAME_CARO) {
                handleCrPacket(sub, r);
            } else if (gameId == AvatarProtocol.MG_GAME_TRUCXANH) {
                handleTxPacket(sub, r);
            } else if (gameId == AvatarProtocol.MG_GAME_AINCRAD) {
                handleAiPacket(sub, r);
            } else if (gameId == AvatarProtocol.MG_GAME_SNAKE) {
                handleSnPacket(sub, r);
            }
        } catch (Exception ignored) { }
    }

    // ----- Vẽ hub -----
    private void drawMgHub() {
        float pw = MG_PW, ph = MG_PH, px = (Ui.W - pw) / 2f, py = (Ui.H - ph) / 2f, top = py + ph;
        batch.setColor(0f, 0f, 0f, 0.45f);
        batch.draw(whiteTex, 0, 0, Ui.W, Ui.H);
        batch.setColor(Color.WHITE);
        batch.draw(Ui.roundedRect((int) pw, (int) ph, 16,
            new Color(0.07f, 0.11f, 0.17f, 0.97f), GLASS_RIM), px, py);
        String sub = mgPage == 0 ? "Chọn một trò chơi"
            : mgPage == 2 ? "Mời bạn bè — ván giao hữu, không nhận quà"
            : mgPage == 3 ? "Bảng xếp hạng — thắng nhiều nhất"
            : mgGameName(mgGame) + " — bàn đang mở";
        drawFarmPanelHeader(px, py, pw, ph, Ui.FA_TROPHY,
            new Color(0.55f, 0.38f, 0.10f, 1f), "Mini game", sub);
        if (mgPage == 0) drawMgSelect(px, py, top);
        else if (mgPage == 1) drawMgLobby(px, py, top);
        else if (mgPage == 3) drawMgTop(px, py, top);
        else drawMgFriends(px, py, top);
        if (!mgStatus.isEmpty()) {
            Ui.fontSmall.setColor(1f, 0.85f, 0.38f, 1f);
            Ui.fontSmall.draw(batch, truncTo(Ui.fontSmall, mgStatus, pw - 56), px + 28, py + 36);
        }
    }

    // ----- Màn chọn game theo MiniGameSelectScr bản chính -----
    // 2 zone (ZONE_1/ZONE_2); lưới neo: lề trái PADDING_X = 48, tối đa
    // MAX_PER_ROW = 6 ô/hàng; icon 96, nhãn cách icon ICON_LABEL_GAP = 12,
    // dòng nhãn LABEL_LINE_H = 32, đệm dưới nhãn LABEL_BOTTOM_PAD = 24,
    // khoảng từ tab zone xuống lưới ANCHOR_GAP_ABOVE = 28.
    // Phân zone theo lệnh Tín 2026-11-05: Khu vực 1 = 3 game casino
    // (Bầu Cua · Tiến Lên · Phỏm — khung Casino riêng, mở thẳng),
    // Khu vực 2 = cả 5 game của hub (Aincrad, Trúc Xanh, Caro,
    // Tàu Chiến, Rắn Thang). [Bản chính suy từ ZONE_1=2/ZONE_2=4 —
    // đã bị lệnh này thay.]
    private int mgZone; // zone đang xem ở màn chọn (0/1)

    private static int[] mgZoneGames(int zone) {
        return zone == 0 ? new int[0] : new int[]{1, 2, 3, 4, 5};
    }

    /** Tên 3 game casino ở Khu vực 1, theo thứ tự thẻ. */
    private static final String[] MG_CASINO_NAMES = {"Bầu Cua", "Tiến Lên", "Phỏm", "Kim Cương"};
    private com.badlogic.gdx.graphics.g2d.TextureRegion[] mgCsIcons;

    /** Icon thẻ casino: Bầu Cua = mặt xúc xắc (img 874 ô 0),
     *  Tiến Lên = mặt lá bài 0, Phỏm = lưng lá bài. */
    private com.badlogic.gdx.graphics.g2d.TextureRegion mgCasinoIcon(int i) {
        if (mgCsIcons == null) mgCsIcons =
            new com.badlogic.gdx.graphics.g2d.TextureRegion[4];
        if (mgCsIcons[i] == null) {
            if (i == 3) {
                Texture t = game.texture("diamond/gems.png");
                if (t != null) mgCsIcons[i] =
                    new com.badlogic.gdx.graphics.g2d.TextureRegion(t, 0, 72, 72, 72);
            } else if (i == 0) {
                Texture t = house.imgTexture(874);
                if (t != null) mgCsIcons[i] =
                    new com.badlogic.gdx.graphics.g2d.TextureRegion(t, 0, 0, 108, 108);
            } else {
                Texture t = cardTexture(i == 1 ? 48 : -1);
                if (t != null) mgCsIcons[i] =
                    new com.badlogic.gdx.graphics.g2d.TextureRegion(t);
            }
        }
        return mgCsIcons[i];
    }

    /** Mở game casino thứ i của Khu vực 1 (đóng hub trước). */
    private void mgOpenCasino(int i) {
        mgCloseHub();
        if (i == 0) startCasinoBauCua();
        else if (i == 1) startCasinoTienLen();
        else if (i == 2) startCasinoPhom();
        else startCasinoDiamond();
    }

    private static String mgSelectIcon(int gameId) {
        switch (gameId) {
            case 1: return "Ghost";      // gốc không có icon select Aincrad
            case 2: return "trucxanh";   // /minigame/select/trucxanh
            case 3: return "caro";       // /minigame/select/caro
            case 4: return "tauchien";   // /minigame/select/tauchien
            case 5: return "snake";
            default: return null;
        }
    }

    /** Ô lưới chọn game thứ i của zone hiện tại: {x trái, y đáy, rộng, cao}. */
    private float[] mgSelectCell(int i, float px, float top) {
        float cw = 120f, ch = 196f;
        return new float[]{px + 48 + i * (cw + 20f), top - 216 - ch, cw, ch};
    }

    private void drawMgSelect(float px, float py, float top) {
        // 2 tab zone
        for (int z = 0; z < 2; z++) {
            float tx = px + 48 + z * 186;
            boolean sel = mgZone == z;
            batch.draw(Ui.roundedRect(170, 44, 11,
                sel ? new Color(0.20f, 0.45f, 0.65f, 1f)
                    : new Color(0.16f, 0.17f, 0.20f, 0.95f), GLASS_RIM),
                tx, top - 188);
            Ui.centered(batch, Ui.font, "Khu vực " + (z + 1), tx + 85, top - 159,
                Color.WHITE);
        }
        if (mgZone == 0) {
            for (int i = 0; i < MG_CASINO_NAMES.length; i++) {
                float[] rc = mgSelectCell(i, px, top);
                float cx = rc[0], cy = rc[1], cw = rc[2], ch = rc[3];
                batch.setColor(Color.WHITE);
                batch.draw(Ui.roundedRect((int) cw, (int) ch, 14,
                    new Color(0.13f, 0.20f, 0.30f, 0.95f), GLASS_RIM), cx, cy);
                com.badlogic.gdx.graphics.g2d.TextureRegion icon = mgCasinoIcon(i);
                if (icon != null) {
                    float iw = icon.getRegionWidth(), ih = icon.getRegionHeight();
                    float sc = Math.min(96f / iw, 96f / ih);
                    float dw = iw * sc, dh = ih * sc;
                    batch.draw(icon, cx + cw / 2f - dw / 2f,
                        cy + ch - 108 + (96 - dh) / 2f, dw, dh);
                } else {
                    batch.draw(Ui.roundedRect(72, 72, 14,
                        new Color(0.45f, 0.30f, 0.12f, 1f), GLASS_RIM),
                        cx + cw / 2f - 36, cy + ch - 96);
                    Ui.centered(batch, Ui.fontTitle,
                        MG_CASINO_NAMES[i].substring(0, 1), cx + cw / 2f,
                        cy + ch - 46, Color.WHITE);
                }
                layout.setText(Ui.font, MG_CASINO_NAMES[i]);
                if (layout.width > cw - 8) {
                    Ui.centered(batch, Ui.fontSmall, MG_CASINO_NAMES[i], cx + cw / 2f,
                        cy + 74, new Color(1f, 1f, 1f, 0.97f));
                } else {
                    Ui.centered(batch, Ui.font, MG_CASINO_NAMES[i], cx + cw / 2f,
                        cy + 76, new Color(1f, 1f, 1f, 0.97f));
                }
                Ui.centered(batch, Ui.fontSmall, "Chơi ngay", cx + cw / 2f,
                    cy + 44, new Color(0.45f, 0.95f, 0.55f, 1f));
                batch.setColor(Color.WHITE);
            }
        }
        int[] games = mgZoneGames(mgZone);
        for (int i = 0; i < games.length; i++) {
            int gid = games[i];
            boolean live = true;
            float[] rc = mgSelectCell(i, px, top);
            float cx = rc[0], cy = rc[1], cw = rc[2], ch = rc[3];
            batch.setColor(1f, 1f, 1f, live ? 1f : 0.55f);
            batch.draw(Ui.roundedRect((int) cw, (int) ch, 14,
                new Color(0.13f, 0.20f, 0.30f, 0.95f), GLASS_RIM), cx, cy);
            String iconName = mgSelectIcon(gid);
            Texture icon = iconName == null ? null : tcTex(iconName);
            if (icon != null) {
                // vẽ vừa khung 96x96 GIỮ tỉ lệ gốc (Ghost cao 68x160,
                // ép vuông sẽ bẹt)
                float iw = icon.getWidth(), ih = icon.getHeight();
                float sc = Math.min(96f / iw, 96f / ih);
                float dw = iw * sc, dh = ih * sc;
                batch.draw(icon, cx + cw / 2f - dw / 2f,
                    cy + ch - 108 + (96 - dh) / 2f, dw, dh);
            } else {
                // game không có icon select: giữ chỗ bằng chữ cái đầu
                batch.draw(Ui.roundedRect(72, 72, 14,
                    new Color(0.25f, 0.55f, 0.30f, 1f), GLASS_RIM),
                    cx + cw / 2f - 36, cy + ch - 96);
                Ui.centered(batch, Ui.fontTitle, "S", cx + cw / 2f, cy + ch - 46,
                    Color.WHITE);
            }
            Ui.centered(batch, Ui.font, mgGameName(gid), cx + cw / 2f, cy + 76,
                new Color(1f, 1f, 1f, 0.97f));
            Ui.centered(batch, Ui.fontSmall, live ? "Chơi ngay" : "Sắp có",
                cx + cw / 2f, cy + 44, live
                    ? new Color(0.45f, 0.95f, 0.55f, 1f)
                    : new Color(1f, 1f, 1f, 0.6f));
            batch.setColor(Color.WHITE);
        }
        // nút Bảng xếp hạng ở đáy panel (Tín thêm 2026-11-03, giữ nguyên)
        batch.draw(Ui.roundedRect(300, 48, 11,
            new Color(0.16f, 0.17f, 0.20f, 0.95f), GLASS_RIM),
            px + (MG_PW - 300) / 2f, py + 70);
        Ui.centered(batch, Ui.font, "Bảng xếp hạng", px + MG_PW / 2f, py + 104,
            Color.WHITE);
        // (3 game casino đã chuyển lên thành thẻ ở Khu vực 1 theo
        // lệnh Tín 2026-11-05 — không còn nút ở đáy panel.)
    }

    private void drawMgLobby(float px, float py, float top) {
        // cột trái: danh sách bàn
        float lx = px + 24, lw = 596f, ly = py + 58, lh = MG_PH - 58 - 118;
        Ui.fontSmall.setColor(1f, 1f, 1f, 0.85f);
        Ui.fontSmall.draw(batch, "Danh sách bàn", lx + 196, top - 96);
        pushPanelClip(lx, ly, lw, lh);
        float rowTop = top - 118 + mgScroll;
        for (int i = 0; i < mgRoomsShown.size(); i++) {
            MgRoom room = mgRoomsShown.get(i);
            float ry = rowTop - (i + 1) * 62f;
            if (ry + 56 < ly || ry > ly + lh) continue;
            batch.draw(Ui.roundedRect((int) lw, 56, 12,
                new Color(0.13f, 0.20f, 0.30f, 0.9f), GLASS_RIM), lx, ry);
            String title = room.n2.isEmpty()
                ? truncTo(Ui.font, room.n1 + " — đang chờ đối thủ", 380)
                : truncTo(Ui.font, room.n1 + "  vs  " + room.n2, 380);
            Ui.font.setColor(1f, 1f, 1f, 0.97f);
            Ui.font.draw(batch, title, lx + 16, ry + 40);
            String st = room.priv ? "Bàn riêng"
                : room.status == 0 ? "Đang chờ"
                : room.status == 1 ? (room.gameId == 4 ? "Đang xếp tàu" : "Đang chuẩn bị")
                : room.status == 2 ? "Đang đấu" : "Đã xong";
            if (room.specs > 0) st += " · " + room.specs + " khán giả";
            Ui.fontSmall.setColor(1f, 1f, 1f, 0.7f);
            Ui.fontSmall.draw(batch, st, lx + 16, ry + 18);
            boolean canJoin = room.status == 0 && room.n2.isEmpty() && !mgInRoom;
            boolean canWatch = !room.priv && room.status >= 1 && room.status <= 2 && !mgInRoom;
            if (canJoin || canWatch) {
                batch.draw(Ui.gradientRect(80, 38, 9, EntryUi.ORANGE_TOP, EntryUi.ORANGE_BOT),
                    lx + lw - 96, ry + 9);
                Ui.centered(batch, Ui.fontSmall, canJoin ? "Vào" : "Xem",
                    lx + lw - 56, ry + 33, Color.WHITE);
            }
        }
        popPanelClip();
        if (mgRoomsShown.isEmpty()) {
            Ui.fontSmall.setColor(1f, 1f, 1f, 0.6f);
            Ui.fontSmall.draw(batch, "Chưa có bàn nào — hãy tạo bàn mới.", lx + 4, top - 150);
        }
        // cột phải: hành động / trạng thái bàn của mình
        float rx = px + 644, rw = 252f;
        if (mgWaiting) {
            Ui.font.setColor(1f, 1f, 1f, 0.97f);
            Ui.font.draw(batch, "Bàn của bạn", rx, top - 96);
            Ui.fontSmall.setColor(1f, 1f, 1f, 0.8f);
            Ui.fontSmall.draw(batch, "Đang chờ đối thủ vào…", rx, top - 126);
            if (!mgMyCode.isEmpty()) {
                Ui.fontSmall.draw(batch, "Mã bàn (gửi cho bạn bè):", rx, top - 176);
                Ui.fontTitle.setColor(1f, 0.85f, 0.38f, 1f);
                Ui.fontTitle.draw(batch, mgMyCode, rx, top - 216);
            }
            batch.draw(Ui.roundedRect((int) rw, 52, 11,
                new Color(0.16f, 0.17f, 0.20f, 0.95f), GLASS_RIM), rx, top - 300);
            Ui.centered(batch, Ui.font, "Huỷ bàn", rx + rw / 2f, top - 266, Color.WHITE);
        } else if (!mgInRoom) {
            batch.draw(Ui.gradientRect((int) rw, 52, 11, EntryUi.ORANGE_TOP, EntryUi.ORANGE_BOT),
                rx, top - 148);
            Ui.centered(batch, Ui.font, "Tạo bàn mới", rx + rw / 2f, top - 114, Color.WHITE);
            // toggle công khai / riêng
            float ty = top - 216;
            batch.draw(Ui.roundedRect(122, 44, 10,
                !mgPriv ? new Color(0.20f, 0.45f, 0.65f, 1f) : new Color(0.16f, 0.17f, 0.20f, 0.95f),
                GLASS_RIM), rx, ty);
            Ui.centered(batch, Ui.fontSmall, "Công khai", rx + 61, ty + 29, Color.WHITE);
            batch.draw(Ui.roundedRect(122, 44, 10,
                mgPriv ? new Color(0.20f, 0.45f, 0.65f, 1f) : new Color(0.16f, 0.17f, 0.20f, 0.95f),
                GLASS_RIM), rx + 130, ty);
            Ui.centered(batch, Ui.fontSmall, "Bàn riêng", rx + 191, ty + 29, Color.WHITE);
            batch.draw(Ui.roundedRect((int) rw, 52, 11,
                new Color(0.16f, 0.17f, 0.20f, 0.95f), GLASS_RIM), rx, top - 288);
            Ui.centered(batch, Ui.font, "Vào bằng mã", rx + rw / 2f, top - 254, Color.WHITE);
            batch.draw(Ui.roundedRect((int) rw, 52, 11,
                new Color(0.16f, 0.17f, 0.20f, 0.95f), GLASS_RIM), rx, top - 356);
            Ui.centered(batch, Ui.font, "Mời bạn bè", rx + rw / 2f, top - 322, Color.WHITE);
            batch.draw(Ui.roundedRect((int) rw, 52, 11,
                new Color(0.16f, 0.17f, 0.20f, 0.95f), GLASS_RIM), rx, top - 424);
            Ui.centered(batch, Ui.font, "Làm mới", rx + rw / 2f, top - 390, Color.WHITE);
        } else {
            Ui.font.setColor(1f, 1f, 1f, 0.97f);
            Ui.font.draw(batch, "Đang trong bàn", rx, top - 96);
            Ui.fontSmall.setColor(1f, 1f, 1f, 0.8f);
            Ui.fontSmall.draw(batch, "Ván đang chuẩn bị…", rx, top - 126);
        }
        // nút quay lại chọn game
        Ui.fontSmall.setColor(0.65f, 0.85f, 1f, 1f);
        Ui.fontSmall.draw(batch, "‹ Chọn game khác", px + 28, top - 96);
    }

    private void mgRequestTop() {
        if (!online() || game.connection == null) {
            mgTopRows.clear();
            mgTopLoaded = true;
            return;
        }
        try { AvatarProtocol.mgTop(game.connection, mgTopGame); }
        catch (Exception ignored) { }
    }

