    // ----- Chạm hub -----
    private boolean mgTouch(float x, float y, int pointer) {
        if (mgInviteIn != null) { mgInviteTouch(x, y); return true; }
        if (mgCodeOpen) { mgCodeTouch(x, y); return true; }
        if (!mgOpen) return false;
        float pw = MG_PW, ph = MG_PH, px = (Ui.W - pw) / 2f, py = (Ui.H - ph) / 2f, top = py + ph;
        // nút đóng (ô vuông đỏ trong header)
        if (x >= px + pw - 54 && x <= px + pw - 18 && y >= top - 54 && y <= top - 18) {
            mgCloseHub();
            return true;
        }
        if (x < px || x > px + pw || y < py || y > top) return true; // nuốt chạm ngoài
        if (mgPage == 0) {
            // tab zone
            for (int z = 0; z < 2; z++) {
                float tx = px + 48 + z * 186;
                if (x >= tx && x <= tx + 170 && y >= top - 188 && y <= top - 144) {
                    mgZone = z;
                    return true;
                }
            }
            // nút Bảng xếp hạng
            if (x >= px + (MG_PW - 300) / 2f && x <= px + (MG_PW + 300) / 2f
                    && y >= py + 70 && y <= py + 118) {
                mgPage = 3;
                mgTopGame = 0;
                mgTopLoaded = false;
                mgRequestTop();
                return true;
            }
            // ô lưới của zone hiện tại: Khu vực 1 = thẻ casino
            // (mở thẳng khung Casino), Khu vực 2 = game hub
            if (mgZone == 0) {
                for (int i = 0; i < MG_CASINO_NAMES.length; i++) {
                    float[] rc = mgSelectCell(i, px, top);
                    if (x >= rc[0] && x <= rc[0] + rc[2]
                            && y >= rc[1] && y <= rc[1] + rc[3]) {
                        mgOpenCasino(i);
                        return true;
                    }
                }
                return true;
            }
            int[] games = mgZoneGames(mgZone);
            for (int i = 0; i < games.length; i++) {
                float[] rc = mgSelectCell(i, px, top);
                if (x >= rc[0] && x <= rc[0] + rc[2]
                        && y >= rc[1] && y <= rc[1] + rc[3]) {
                    mgGame = games[i];
                    refreshMgRoomsShown();
                    mgPage = 1;
                    mgScroll = 0f;
                    mgRequestList();
                    return true;
                }
            }
            return true;
        }
        // liên kết quay lại (góc trái, cạnh tiêu đề phụ)
        if (x >= px + 20 && x <= px + 190 && y >= top - 108 && y <= top - 78) {
            mgPage = mgPage == 2 ? 1 : 0;
            mgScroll = 0f;
            if (mgPage == 1) mgRequestList();
            return true;
        }
        float lx = px + 24, lw = mgPage == 2 ? MG_PW - 48 : 596f;
        float ly = py + 58, lh = MG_PH - 58 - 118;
        if (mgPage == 1) {
            float rx = px + 644, rw = 252f;
            if (mgWaiting) {
                if (x >= rx && x <= rx + rw && y >= top - 300 && y <= top - 248) {
                    mgCloseHub();
                    return true;
                }
            } else if (!mgInRoom) {
                if (x >= rx && x <= rx + rw && y >= top - 148 && y <= top - 96) {
                    try {
                        AvatarProtocol.mgCreate(game.connection, mgGame, mgPriv);
                    } catch (Exception ignored) { }
                    return true;
                }
                if (y >= top - 216 && y <= top - 172) {
                    if (x >= rx && x <= rx + 122) { mgPriv = false; return true; }
                    if (x >= rx + 130 && x <= rx + 252) { mgPriv = true; return true; }
                }
                if (x >= rx && x <= rx + rw && y >= top - 288 && y <= top - 236) {
                    mgCodeOpen = true;
                    mgCode = "";
                    return true;
                }
                if (x >= rx && x <= rx + rw && y >= top - 356 && y <= top - 304) {
                    mgPage = 2;
                    mgScroll = 0f;
                    requestFriends();
                    return true;
                }
                if (x >= rx && x <= rx + rw && y >= top - 424 && y <= top - 372) {
                    mgRequestList();
                    return true;
                }
            }
        }
        if (mgPage == 3) {
            String[] tabs = {"Tổng", "Aincrad", "Trúc Xanh", "Cờ Caro", "Tàu Chiến"};
            int[] tabGame = {0, 1, 2, 3, 4};
            float tw = 160f, tx0 = px + (MG_PW - (5 * tw + 4 * 10)) / 2f;
            if (y >= top - 164 && y <= top - 120) {
                for (int i = 0; i < 5; i++) {
                    float tx = tx0 + i * (tw + 10);
                    if (x >= tx && x <= tx + tw) {
                        mgTopGame = tabGame[i];
                        mgTopLoaded = false;
                        mgScroll = 0f;
                        mgRequestTop();
                        return true;
                    }
                }
            }
            // vùng danh sách BXH: chỉ kéo cuộn
            float bx = px + 120, bw = MG_PW - 240;
            if (x >= bx && x <= bx + bw && y >= ly && y <= ly + lh) {
                mgPointer = pointer;
                mgDragStartY = y;
                mgDragStartScroll = mgScroll;
                mgDragMoved = 0f;
                mgPendingRoom = -1;
            }
            return true;
        }
        // vùng danh sách: bắt đầu kéo cuộn + ghi nhận chạm hàng (xử lý ở touchUp)
        if (x >= lx && x <= lx + lw && y >= ly && y <= ly + lh) {
            mgPointer = pointer;
            mgDragStartY = y;
            mgDragStartScroll = mgScroll;
            mgDragMoved = 0f;
            mgPendingRoom = -1;
            float rowTop = top - 118 + mgScroll;
            int n = mgPage == 2 ? friends.size() : mgRoomsShown.size();
            for (int i = 0; i < n; i++) {
                float ry = rowTop - (i + 1) * 62f;
                if (y >= ry && y <= ry + 56 && x >= lx + lw - 96 && x <= lx + lw - 16) {
                    if (mgPage == 2) {
                        mgPendingRoom = i;
                        mgPendingKind = 2;
                    } else {
                        MgRoom room = mgRoomsShown.get(i);
                        boolean canJoin = room.status == 0 && room.n2.isEmpty() && !mgInRoom;
                        boolean canWatch = !room.priv && room.status >= 1 && room.status <= 2 && !mgInRoom;
                        if (canJoin) { mgPendingRoom = i; mgPendingKind = 0; }
                        else if (canWatch) { mgPendingRoom = i; mgPendingKind = 1; }
                    }
                    break;
                }
            }
            return true;
        }
        return true;
    }

