    // ===== TÀU CHIẾN: chạm =====
    private int[] tcCellAt(float x, float y, int boardIdx) {
        float cell = tcCell(), view = tcView(), bx = tcBx(boardIdx), top = tcTop();
        if (x < bx || x >= bx + view || y <= top - view || y > top) return null;
        int col = (int) ((x - bx + tcPanX(boardIdx)) / cell);
        int row = (int) ((top + tcPanY(boardIdx) - y) / cell);
        if (row < 0 || row >= TC_N || col < 0 || col >= TC_N) return null;
        return new int[]{row, col};
    }

    private boolean tcTouch(float x, float y, int pointer) {
        if (!tcOpen) return false;
        if (tcLeaveAsk) {
            float pw = 560f, ph = 260f, px = (Ui.W - pw) / 2f, py = (Ui.H - ph) / 2f;
            if (x >= px + 60 && x <= px + 220 && y >= py + 36 && y <= py + 90) {
                tcLeaveAsk = false;
                return true;
            }
            if (x >= px + pw - 220 && x <= px + pw - 60 && y >= py + 36 && y <= py + 90) {
                tcLeaveAsk = false;
                tcLeaveRoom();
                return true;
            }
            return true;
        }
        boolean spec = tcSeat == 2;
        // nút rời bàn / ngừng xem (dải dưới trong khung sáng)
        if (x >= 1108 && x <= 1244 && y >= 24 && y <= 72) {
            if (spec) tcLeaveRoom();
            else tcLeaveAsk = true;
            return true;
        }
        if (spec) return true;
        // nút đuổi (chủ bàn, pha xếp)
        if (tcSeat == 0 && tcPhase == 1 && !tcName1.isEmpty()
            && x >= 1148 && x <= 1240 && y >= 648 && y <= 684) {
            try { AvatarProtocol.tcKick(game.connection); } catch (Exception ignored) { }
            return true;
        }
        if (tcPhase == 1) {
            if (!tcPlacedOk) {
                // nút xoay nhanh ở góc bàn
                if (x >= tcBx(0) + tcView() - 64 && x <= tcBx(0) + tcView()
                    && y >= tcTop() - 64 && y <= tcTop()) {
                    tcRotateAction();
                    return true;
                }
                // hàng nút dưới panel tàu
                if (y >= 118 && y <= 170) {
                    if (x >= 600 && x <= 710) { tcRotateAction(); return true; }
                    if (x >= 724 && x <= 834) { tcRemoveSelected(); return true; }
                    if (x >= 848 && x <= 1038) {
                        if (tcAutoPlace()) {
                            tcPlaceError = "";
                            tcSelShip = -1;
                            tcSelType = -1;
                        } else {
                            tcPlaceError = "Chưa xếp được — thử lại nhé.";
                        }
                        return true;
                    }
                    if (x >= 1052 && x <= 1240 && tcAllPlaced()) {
                        tcSendFleet();
                        return true;
                    }
                }
                // danh sách tàu ListShip: 5 hàng theo độ dài 5..1
                int[] lens = {5, 4, 3, 2, 1};
                for (int i = 0; i < 5; i++) {
                    float rowTop = 190 + 425 - i * 85f;
                    if (x >= 600 && x <= 1060 && y >= rowTop - 85 && y <= rowTop) {
                        if (tcRemaining(lens[i]) > 0) {
                            tcSelType = lens[i];
                            tcSelShip = -1;
                        }
                        return true;
                    }
                }
                // bàn của mình: kéo tàu / đặt tàu mới
                int[] cell = tcCellAt(x, y, 0);
                if (cell != null) {
                    for (int i = 0; i < tcMyFleet.size(); i++) {
                        TcShip s = tcMyFleet.get(i);
                        if (!s.placed) continue;
                        for (int k = 0; k < s.len; k++) {
                            int rr = s.row + (s.vert == 1 ? k : 0);
                            int cc = s.col + (s.vert == 1 ? 0 : k);
                            if (rr == cell[0] && cc == cell[1]) {
                                tcSelShip = i;
                                tcSelType = -1;
                                tcDragIdx = i;
                                tcPointer = pointer;
                                tcDragOffR = cell[0] - s.row;
                                tcDragOffC = cell[1] - s.col;
                                tcDragX = x;
                                tcDragY = y;
                                return true;
                            }
                        }
                    }
                    if (tcSelType > 0) {
                        TcShip s = tcUnplaced(tcSelType);
                        if (s != null) {
                            String err = tcPlaceCheck(s.len, cell[0], cell[1], tcSelVert, s);
                            if (err == null) {
                                s.row = cell[0]; s.col = cell[1];
                                s.vert = tcSelVert ? 1 : 0; s.placed = true;
                                tcPlaceError = "";
                                tcSelShip = tcMyFleet.indexOf(s);
                                if (tcRemaining(tcSelType) == 0) tcSelType = -1;
                            } else {
                                tcPlaceError = err;
                            }
                        }
                        return true;
                    }
                    tcSelShip = -1;
                    return true;
                }
            } else {
                // đã chốt đội hình: nút Sẵn sàng
                if (x >= 1052 && x <= 1240 && y >= 118 && y <= 170 && !tcReadyMe) {
                    try { AvatarProtocol.tcReady(game.connection); }
                    catch (Exception ignored) { }
                    return true;
                }
            }
            return true;
        }
        if (tcPhase == 2) {
            if (tcTurn == tcSeat) {
                int[] cell = tcCellAt(x, y, 1);
                if (cell != null) {
                    int idx = cell[0] * TC_N + cell[1];
                    if (tcShotsMine[idx] == 0) tcSelCell = idx;
                    return true;
                }
                if (x >= 530 && x <= 750 && y >= 36 && y <= 92 && tcSelCell >= 0) {
                    try {
                        AvatarProtocol.tcShoot(game.connection, tcSelCell / TC_N, tcSelCell % TC_N);
                    } catch (Exception ignored) { }
                    return true;
                }
            }
            return true;
        }
        if (tcPhase == 3) {
            if (x >= 430 && x <= 620 && y >= 36 && y <= 92) {
                try { AvatarProtocol.mgRematch(game.connection); } catch (Exception ignored) { }
                tcBanner = "Đã gửi lời rủ ván mới — chờ đối thủ nhận.";
                return true;
            }
            if (x >= 660 && x <= 850 && y >= 36 && y <= 92) {
                tcLeaveRoom();
                mgOpen = true;
                mgPage = 1;
                mgRequestList();
                return true;
            }
            return true;
        }
        return true;
    }

    private void tcRotateAction() {
        if (tcSelShip >= 0 && tcSelShip < tcMyFleet.size()) {
            TcShip s = tcMyFleet.get(tcSelShip);
            if (s.placed) {
                boolean nv = s.vert == 0;
                if (tcPlaceCheck(s.len, s.row, s.col, nv, s) == null) {
                    s.vert = nv ? 1 : 0;
                    tcPlaceError = "";
                } else {
                    tcPlaceError = "Không xoay được ở vị trí này.";
                }
            }
        } else if (tcSelType > 0) {
            tcSelVert = !tcSelVert;
        }
    }

    private void tcRemoveSelected() {
        if (tcSelShip >= 0 && tcSelShip < tcMyFleet.size()) {
            TcShip s = tcMyFleet.get(tcSelShip);
            s.placed = false;
            s.hits = 0;
            tcSelShip = -1;
        }
    }

    private void tcDropShip(float x, float y) {
        if (tcDragIdx < 0 || tcDragIdx >= tcMyFleet.size()) return;
        TcShip s = tcMyFleet.get(tcDragIdx);
        int[] cell = tcCellAt(x, y, 0);
        if (cell == null) return;
        int nr = cell[0] - tcDragOffR, nc = cell[1] - tcDragOffC;
        if (nr == s.row && nc == s.col) return; // thả lại chỗ cũ (chạm nhẹ = chọn)
        String err = tcPlaceCheck(s.len, nr, nc, s.vert == 1, s);
        if (err == null) {
            s.row = nr;
            s.col = nc;
            tcPlaceError = "";
        } else {
            tcPlaceError = err;
        }
    }

    private void tcLeaveRoom() {
        try { AvatarProtocol.mgLeave(game.connection); } catch (Exception ignored) { }
        tcOpen = false;
        mgInRoom = false;
        mgWaiting = false;
        mgRoomId = -1;
        tcDragIdx = -1;
    }

