        batch.setColor(1f, 1f, 1f, 1f);
        batch.draw(Ui.gradientRect((int) Ui.W, (int) Ui.H, 0,
            new Color(0.05f, 0.10f, 0.20f, 1f), new Color(0.03f, 0.06f, 0.12f, 1f)), 0, 0);
