    /** Giây còn lại của lượt hiện tại (đếm ngược 30s như bản port Tàu Chiến). */
    private String mgTurnClock(long turnAt) {
        int left = 30 - (int) ((System.currentTimeMillis() - turnAt) / 1000);
        if (left < 0) left = 0;
        return " · " + left + "s";
    }

